#include <stdio.h>
#include <stdlib.h>
#include <gpiod/gpiod.h>

int main(int argc, char *argv[]) {
    gpiod_t *gpiod;
    gpiod_device_t *device;
    gpiod_request_t *request;
    gpiod_event_t *event;
    int state = 0;

    // Initialize libgpiod
    if (gpiod_init() != 0) {
        fprintf(stderr, "Error initializing libgpiod: %s\n", gpiod_strerror());
        return 1;
    }

    // Open the device
    if ((device = gpiod_device_open("gpio-2", GpioDirectionOutput)) != NULL) {
        if (gpiod_device_get_request(device, &request) != 0) {
            fprintf(stderr, "Error getting request: %s\n", gpiod_strerror());
            gpiod_device_close(device);
            return 1;
        }

        // Set the initial state
        if (gpiod_request_set_value(request, 0, state) != 0) {
            fprintf(stderr, "Error setting initial state: %s\n", gpiod_strerror());
            gpiod_device_close(device);
            gpiod_request_close(request);
            return 1;
        }

        // Create an event to report the state
        if ((event = gpiod_event_create(request, "state")) != NULL) {
            if (gpiod_event_bind(event, GpioEventState, state)) {
                fprintf(stderr, "Error binding event: %s\n", gpiod_strerror());
                gpiod_event_destroy(event);
                gpiod_request_close(request);
                gpiod_device_close(device);
                return 1;
            }

            // Main loop
            while (1) {
                // Get the current state
                if (gpiod_event_get_value(event) != 0) {
                    fprintf(stderr, "Error getting state: %s\n", gpiod_strerror());
                    gpiod_event_destroy(event);
                    gpiod_request_close(request);
                    gpiod_device_close(device);
                    return 1;
                }

                // Toggle the state
                state = 1 - state;
                if (gpiod_request_set_value(request, 0, state) != 0) {
                    fprintf(stderr, "Error toggling state: %s\n", gpiod_strerror());
                    gpiod_event_destroy(event);
                    gpiod_request_close(request);
                    gpiod_device_close(device);
                    return 1;
                }

                // Sleep for 2 seconds
                sleep(2);
            }
        } else {
            fprintf(stderr, "Error creating event: %s\n", gpiod_strerror());
            gpiod_request_close(request);
            gpiod_device_close(device);
            return 1;
        }
    } else {
        fprintf(stderr, "Error opening device: %s\n", gpiod_strerror());
        return 1;
    }

    // Release the device on exit
    gpiod_device_close(device);
    gpiod_request_close(request);
    gpiod_event_destroy(event);
    gpiod_exit();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    gpiod_init();

    // Open the GPIO device
    gpiod_device *dev = gpiod_device_open("gpio-2", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        gpiod_exit();
        return 1;
    }

    // Open the GPIO pin
    gpiod_pin *pin = gpiod_pin_open(dev, 2, GPIOD_PIN_TYPE_OUTPUT);
    if (!pin) {
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the initial state of the pin
    gpiod_pin_set_value(pin, 0);

    // Set up a callback to toggle the pin every 0.1 seconds
    gpiod_pin_set_callback(pin, GPIOD_PIN_EDGE_BOTH, gpiod_pin_callback, (void *) 2);

    // Start the callback
    gpiod_pin_enable(pin);

    // Main loop
    while (1) {
        // Print the current state of the pin
        gpiod_pin_get_value(pin, 0, NULL);
        printf("Pin 2: %d\n", gpiod_pin_get_value(pin, 0));

        // Sleep for 0.1 seconds
        usleep(100000);
    }

    // Clean up
    gpiod_pin_disable(pin);
    gpiod_pin_close(pin);
    gpiod_device_close(dev);
    gpiod_exit();

    return 0;
}

// Callback function to toggle the pin
void gpiod_pin_callback(gpiod_pin *pin, gpiod_event event, void *user_data) {
    gpiod_pin_set_value(pin, !*(int *)user_data);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <gpiod/gpiod.h>

#define GPIO_PIN 2
#define GPIO_DIR 0x00
#define GPIO_VALUE 0x01

int main() {
    gpiod_context_t ctx;
    gpiod_gpio_t gpio;
    gpiod_gpio_request_t req;
    gpiod_gpio_value_t value;

    // Initialize libgpiod
    if (gpiod_init(&ctx) != 0) {
        fprintf(stderr, "gpiod_init failed\n");
        return 1;
    }

    // Open the GPIO device
    if (gpiod_gpio_open(&ctx, GPIO_PIN, &req) != 0) {
        fprintf(stderr, "gpiod_gpio_open failed: %d\n", req.err);
        gpiod_gpio_close(&req);
        gpiod_exit(&ctx);
        return 1;
    }

    // Get the GPIO device
    if (gpiod_gpio_get(&req, &gpio) != 0) {
        fprintf(stderr, "gpiod_gpio_get failed: %d\n", req.err);
        gpiod_gpio_close(&req);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set the GPIO pin direction
    if (gpiod_gpio_direction(&req, GPIO_DIR, GPIO_VALUE) != 0) {
        fprintf(stderr, "gpiod_gpio_direction failed: %d\n", req.err);
        gpiod_gpio_close(&req);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set the GPIO pin value
    if (gpiod_gpio_value(&req, GPIO_PIN, GPIO_VALUE) != 0) {
        fprintf(stderr, "gpiod_gpio_value failed: %d\n", req.err);
        gpiod_gpio_close(&req);
        gpiod_exit(&ctx);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the GPIO pin value
        gpiod_gpio_value(&req, GPIO_PIN, &value);
        if (value < 0) {
            fprintf(stderr, "gpiod_gpio_value failed: %d\n", value);
            gpiod_gpio_close(&req);
            gpiod_exit(&ctx);
            return 1;
        }

        // Print the GPIO pin value
        printf("GPIO %d: %d\n", GPIO_PIN, value);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    gpiod_gpio_close(&req);
    gpiod_exit(&ctx);
    return 0;
}

#include <stdio.h>
