        perror("gpioInitialise");
        return 1;
    }

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Check if device is present
    ret = ioctl(fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Create I2C client
    client = i2c_new_client(fd, I2C_ADDRESS, NULL);
    if (!client) {
        perror("i2c_new_client");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Create I2C device
    dev = i2c_get_clientdata(client);
    if (!dev) {
        perror("i2c_get_clientdata");
        i2c_release_client(client);
        close(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read temperature
        ret = i2c_master_send(client, &msg, 1, sizeof(msg));
        if (ret < 0) {
            perror("i2c_master_send");
            break;
        }

        ret = i2c_master_recv(client, &reply, 1, sizeof(reply));
        if (ret < 0) {
            perror("i2c_master_recv");
            break;
        }

        // Check if device is present
        if (reply->ack) {
            printf("Temperature: %d\n", reply->data[0]);
        } else {
            printf("Device not found\n");
            break;
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Release I2C device
    i2c_release_client(client);

    // Close I2C device
    close(fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

