#include <stdlib.h>
#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return ret;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-17", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        fprintf(stderr, "Failed to open GPIO device\n");
        gpiod_exit();
        return 1;
    }

    // Open the GPIO pin
    struct gpiod_pin *pin = gpiod_pin_open(dev, 17, GPIOD_PIN_MODE_OUTPUT);
    if (!pin) {
        fprintf(stderr, "Failed to open GPIO pin 17\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Open the GPIO pin
    pin = gpiod_pin_open(dev, 18, GPIOD_PIN_MODE_OUTPUT);
    if (!pin) {
        fprintf(stderr, "Failed to open GPIO pin 18\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the initial state of the pins
    gpiod_pin_set_value(pin, 0);

    // Wait for 5 seconds
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    while (ts.tv_sec < ts.tv_sec + 5) {
        gpiod_pin_set_value(pin, 1);
        gpiod_pin_set_value(pin, 0);
        nanosleep(&ts, &ts);
    }

    // Close the GPIO pins
    gpiod_pin_close(pin);
    gpiod_device_close(dev);

    // Release the GPIO device
    gpiod_exit();

    return 0;
}

