        return 1;
    }

    // Get the GPIO number for GPIO 18 (BCM numbering)
    int gpio = gpioGetPin(18);

    if (gpio < 0) {
        fprintf(stderr, "Error getting GPIO 18: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set the GPIO as an output
    if (gpioMode(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO 18 as output: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set the initial PWM value
    int pwmValue = 100; // 0-100

    while (1) {
        // Set the PWM value
        if (gpioWrite(gpio, pwmValue) < 0) {
            fprintf(stderr, "Error setting PWM value: %s\n", strerror(errno));
            gpioTerminate();
            return 1;
        }

        // Print the current PWM value
        printf("PWM value: %d\n", pwmValue);

        // Sleep for 0.5 seconds
        sleep(0.5);

        // Decrease the PWM value
        pwmValue = (pwmValue > 0) ? pwmValue - 1 : 0;
    }

    // Release the GPIO
    gpioTerminate();

    return 0;
}

