        perror("gpioInitialise");
        return 1;
    }

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Check if device is present
    status = ioctl(fd, I2C_SLAVE, I2C_ADDRESS);
    if (status < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Create I2C client
    client = i2c_new_client(fd, I2C_ADDRESS, 0);
    if (!client) {
        perror("i2c_new_client");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Create I2C device
    dev = i2c_get_clientdata(client);
    if (!dev) {
