        i2c_release_client(client);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set up ADC
    ret = ioctl(dev, I2C_SLAVE, ADC_CHANNEL);
    if (ret < 0) {
        perror("ioctl");
        i2c_release_client(client);
        close(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read ADC value
        ret = i2c_master_read(client, buf, 3, 0);
        if (ret < 0) {
            perror("i2c_master_read");
            break;
        }

        // Check if reading is valid
        if (buf[0] == 0x00) {
            printf("Invalid reading\n");
            break;
        }

        // Convert to voltage
        value = (buf[0] << 8) | buf[1];
        value /= 240;

        printf("%f\n", value / 1000.0);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Release resources
    i2c_release_client(client);
    close(fd);
    gpioTerminate();

    return 0;
}

