int main(int argc, char *argv[]) {
    gpiod_context_t ctx;
    gpiod_gpio_t gpio;
    gpiod_gpio_request_t req;
    gpiod_gpio_value_t value;

    // Initialize libgpiod
    if (gpiod_init(&ctx) != 0) {
        fprintf(stderr, "gpiod_init failed\n");
        return EXIT_FAILURE;
    }

    // Open GPIO device
    if (gpiod_gpio_open(&ctx, GPIO_PIN, &req) != 0) {
        fprintf(stderr, "gpiod_gpio_open failed\n");
        gpiod_exit(&ctx);
        return EXIT_FAILURE;
    }

    // Set up GPIO direction and value
    if (gpiod_gpio_direction(&req, GPIO_DIR, GPIO_VALUE) != 0) {
        fprintf(stderr, "gpiod_gpio_direction failed\n");
        gpiod_gpio_close(&req);
        gpiod_exit(&ctx);
        return EXIT_FAILURE;
