    if (gpiod_gpio_value(&req, GPIO_VALUE, GPIO_VALUE) != 0) {
        fprintf(stderr, "gpiod_gpio_value failed\n");
        gpiod_gpio_close(&req);
        gpiod_exit(&ctx);
        return EXIT_FAILURE;
    }

