int main() {
    gpiod_context_t ctx;
    gpiod_device_t *dev;
    gpiod_gpio_t *gpio;
    gpiod_gpio_request_t req;
    gpiod_gpio_flags_t flags;

    // Initialize libgpiod
    if (gpiod_init(&ctx) != 0) {
        fprintf(stderr, "gpiod_init failed\n");
        return 1;
    }

    // Get the device handle
    if (gpiod_device_get(&ctx, 0, &dev) != 0) {
        fprintf(stderr, "gpiod_device_get failed\n");
        gpiod_exit(&ctx);
        return 1;
    }

    // Get the GPIO device
    if (gpiod_device_get_gpio(dev, 4, &gpio) != 0) {
        fprintf(stderr, "gpiod_device_get_gpio failed\n");
        gpiod_device_put(dev);
        gpiod_exit(&ctx);
        return 1;
    }

    // Get the GPIO request
    if (gpiod_gpio_get_request(gpio, &req) != 0) {
        fprintf(stderr, "gpiod_gpio_get_request failed\n");
        gpiod_gpio_put(gpio);
        gpiod_device_put(dev);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set the GPIO flags
    flags = GpioDirectionOutput;
    if (gpiod_gpio_set_flags(gpio, flags) != 0) {
        fprintf(stderr, "gpiod_gpio_set_flags failed\n");
        gpiod_gpio_put(gpio);
        gpiod_device_put(dev);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set the GPIO value
    if (gpiod_gpio_set_value(gpio, 1) != 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed\n");
        gpiod_gpio_put(gpio);
        gpiod_device_put(dev);
        gpiod_exit(&ctx);
        return 1;
    }

    // Main loop
    while (1) {
        // Get the current state
        gpiod_gpio_get_value(gpio, &req.value);

        // Print the state
        printf("%d\n", req.value);

        // Sleep for 0.05 seconds
        usleep(50000);

        // Toggle the GPIO value
        gpiod_gpio_set_value(gpio, !req.value);
    }

    // Release the GPIO request
    gpiod_gpio_put(gpio);

    // Release the GPIO device
    gpiod_device_put(dev);

    // Release the device handle
    gpiod_device_put(dev);

    // Exit libgpiod
    gpiod_exit(&ctx);

