#define I2C_ADDRESS 0x40
#define I2C_REG_T0C 0x00
#define I2C_REG_T1C 0x01
#define I2C_REG_T2C 0x02
#define I2C_REG_T3C 0x03

int main() {
    int fd;
    struct i2c_client *client;
    struct i2c_dev *dev;
    unsigned char buf[2];
    unsigned char t0c, t1c, t2c, t3c;
    int ret;
    struct timespec delay;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Get I2C device handle
    ret = ioctl(fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Map I2C device memory
    dev = mmap(NULL, 256, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (dev == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return 1;
    }

    while (1) {
        // Read temperature registers
        ret = read(dev, &buf, 2);
        if (ret < 2) {
            perror("read");
            break;
        }

        // Check if device is present
        if (buf[0] == 0x00) {
            printf("Device not found\n");
            break;
        }

        // Check if reading is valid
        if (buf[0] & 0x80) {
            printf("Invalid reading\n");
            break;
        }

        // Extract temperature values
        t0c = buf[0] & 0x3F;
        t1c = buf[1] & 0x3F;

        // Print temperature values
        printf("Temperature: %d.%02d C\n", t0c, t1c);

        // Wait for 5 seconds
        nanosleep(&delay, NULL);
        delay.tv_sec = 5;
        delay.tv_nsec = 0;
    }

    // Release I2C device
    munmap(dev, 256);
    close(fd);

    return 0;
}

