#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    gpiod_init();

    // Open the GPIO device
    gpiod_device *dev = gpiod_device_open("gpio-0", 0);
    if (!dev) {
        gpiod_perror("Failed to open GPIO device");
        return 1;
    }

    // Open the GPIO pins
    gpiod_pin *pin8 = gpiod_pin_open(dev, 8, GPIOD_DIR_OUT);
    gpiod_pin *pin9 = gpiod_pin_open(dev, 9, GPIOD_DIR_OUT);
    gpiod_pin *pin10 = gpiod_pin_open(dev, 10, GPIOD_DIR_OUT);
    gpiod_pin *pin11 = gpiod_pin_open(dev, 11, GPIOD_DIR_OUT);
    gpiod_pin *pin23 = gpiod_pin_open(dev, 23, GPIOD_DIR_OUT);
    gpiod_pin *pin24 = gpiod_pin_open(dev, 24, GPIOD_DIR_OUT);
    if (!pin8 || !pin9 || !pin10 || !pin11 || !pin23 || !pin24) {
        gpiod_perror("Failed to open GPIO pins");
        gpiod_device_close(dev);
        return 1;
    }

    // Set the pins to output
    gpiod_pin_set_direction(pin8, GPIOD_DIR_OUT);
    gpiod_pin_set_direction(pin9, GPIOD_DIR_OUT);
    gpiod_pin_set_direction(pin10, GPIOD_DIR_OUT);
    gpiod_pin_set_direction(pin11, GPIOD_DIR_OUT);
    gpiod_pin_set_direction(pin23, GPIOD_DIR_OUT);
    gpiod_pin_set_direction(pin24, GPIOD_DIR_OUT);

    // Set the pins to high
    gpiod_pin_set_value(pin8, 1);
    gpiod_pin_set_value(pin9, 1);
    gpiod_pin_set_value(pin10, 1);
    gpiod_pin_set_value(pin11, 1);
    gpiod_pin_set_value(pin23, 1);
    gpiod_pin_set_value(pin24, 1);

    // Report the initial state
    printf("Initial state: pin8=1, pin9=1, pin10=1, pin11=1, pin23=1, pin24=1\n");

    // Main loop
    for (int i = 0; i < 256; i++) {
        // Toggle the pins
        gpiod_pin_set_value(pin8, !gpiod_pin_get_value(pin8));
        gpiod_pin_set_value(pin9, !gpiod_pin_get_value(pin9));
        gpiod_pin_set_value(pin10, !gpiod_pin_get_value(pin10));
        gpiod_pin_set_value(pin11, !gpiod_pin_get_value(pin11));
        gpiod_pin_set_value(pin23, !gpiod_pin_get_value(pin23));
        gpiod_pin_set_value(pin24, !gpiod_pin_get_value(pin24));

        // Report the current state
        printf("Cycle %d: pin8=%d, pin9=%d, pin10=%d, pin11=%d, pin23=%d, pin24=%d\n",
               i, gpiod_pin_get_value(pin8), gpiod_pin_get_value(pin9), gpiod_pin_get_value(pin10),
               gpiod_pin_get_value(pin11), gpiod_pin_get_value(pin23), gpiod_pin_get_value(pin24));
    }

    // Release the pins
    gpiod_pin_close(pin8);
    gpiod_pin_close(pin9);
    gpiod_pin_close(pin10);
    gpiod_pin_close(pin11);
    gpiod_pin_close(pin23);
    gpiod_pin_close(pin24);

    // Close the GPIO device
    gpiod_device_close(dev);

    // Finalize libgpiod
    gpiod_finalize();

    return 0;
}

