    printf("State after 2 seconds: %d\n", gpiod_gpio_get_value(gpio));

    // Close the GPIO pin and device
    gpiod_gpio_close(gpio);
    gpiod_device_close(dev);

    // Release libgpiod
    gpiod_exit();

