#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-2", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Get the GPIO pin
    struct gpiod_gpio *gpio = gpiod_gpio_open(dev, 2);
    if (!gpio) {
        fprintf(stderr, "gpiod_gpio_open failed\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the initial state to low
    ret = gpiod_gpio_set_value(gpio, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set up the event handler
    struct gpiod_event_handler eh;
    eh.callback = gpiod_gpio_event_handler;
    eh.data = gpio;
    eh.flags = GPIOD_EVENT_MASK_HIGH | GPIOD_EVENT_MASK_LOW;
    ret = gpiod_gpio_set_event_handler(gpio, &eh);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_event_handler failed: %d\n", ret);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read the current state
        int state = gpiod_gpio_get_value(gpio);
        if (state < 0) {
            fprintf(stderr, "gpiod_gpio_get_value failed: %d\n", state);
            gpiod_gpio_close(gpio);
            gpiod_device_close(dev);
            gpiod_exit();
            return EXIT_FAILURE;
        }

        // Print the state
        printf("%d\n", state);

        // Wait for 1 second
        usleep(1000000);
    }

    // Clean up
    gpiod_gpio_close(gpio);
    gpiod_device_close(dev);
    gpiod_exit();

    return EXIT_SUCCESS;
}

void gpiod_gpio_event_handler(struct gpiod_event *event) {
    struct gpiod_gpio *gpio = event->data;
    int state = gpiod_gpio_get_value(gpio);
    if (state < 0) {
        fprintf(stderr, "gpiod_gpio_get_value failed: %d\n", state);
        return;
    }

    // Print the state
    printf("%d\n", state);
}

