        if (gpiod_event_set_state(event, state) != 0) {
            fprintf(stderr, "Error setting state: %s\n", gpiod_strerror());
            gpiod_event_destroy(event);
            gpiod_request_destroy(request);
            gpiod_close(&gpiod);
            gpiod_exit();
            return 1;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Release the request and device
    gpiod_request_destroy(request);
    gpiod_close(&gpiod);

    // Exit cleanly
    gpiod_exit();
    return 0;
