#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-2", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Get the GPIO pin
    struct gpiod_gpio *gpio = gpiod_gpio_open(dev, 2);
    if (!gpio) {
        fprintf(stderr, "gpiod_gpio_open failed\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the initial state
    ret = gpiod_gpio_set_value(gpio, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Get the current state
        int state = gpiod_gpio_get_value(gpio);
        printf("State: %d\n", state);

        // Sleep for 0.1 seconds
        usleep(100000);

        // Toggle the state
        ret = gpiod_gpio_set_value(gpio, !state);
        if (ret < 0) {
            fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
            gpiod_gpio_close(gpio);
            gpiod_device_close(dev);
            gpiod_exit();
            return EXIT_FAILURE;
        }
    }

    // Clean up
    gpiod_gpio_close(gpio);
    gpiod_device_close(dev);
    gpiod_exit();
    return EXIT_SUCCESS;
}

