    gpiod_init();

    // Open the GPIO device
    gpiod_device *dev = gpiod_device_open("gpio-2", GPIOD_DEVICE_TYPE_GPIO, NULL);
    if (!dev) {
        gpiod_exit();
        return 1;
    }

    // Open the GPIO device for GPIO 3
    gpiod_device *gpio3_dev = gpiod_device_open(dev, "gpio-3", GPIOD_DEVICE_TYPE_GPIO, NULL);
    if (!gpio3_dev) {
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Get the GPIO 2 and GPIO 3 devices
    gpiod_gpio *gpio2 = gpiod_gpio_open(gpio3_dev, 2, GPIOD_GPIO_DIR_IN);
    if (!gpio2) {
        gpiod_device_close(gpio3_dev);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    gpiod_gpio *gpio3 = gpiod_gpio_open(gpio3_dev, 3, GPIOD_GPIO_DIR_OUT);
    if (!gpio3) {
        gpiod_gpio_close(gpio2);
        gpiod_device_close(gpio3_dev);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the initial state of GPIO 3 to low
    gpiod_gpio_write(gpio3, 0);

    // Main loop
    while (1) {
        // Read the state of GPIO 2
        uint8_t state = gpiod_gpio_read(gpio2);
        if (state == 0) {
            // If GPIO 2 is low, set GPIO 3 to high
            gpiod_gpio_write(gpio3, 1);
        } else {
            // If GPIO 2 is high, set GPIO 3 to low
            gpiod_gpio_write(gpio3, 0);
        }

        // Print the state to standard output
        printf("%d\n", state);

        // Sleep for 0.5 seconds
        usleep(500000);
    }

    // Release the GPIO devices
    gpiod_gpio_close(gpio3);
    gpiod_gpio_close(gpio2);
    gpiod_device_close(gpio3_dev);
    gpiod_device_close(dev);

    // Exit libgpiod
    gpiod_exit();
    return 0;
}

