    if (!pin) {
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the initial state of the pin
    gpiod_pin_set_value(pin, 1);

    // Set up a callback to toggle the pin every 0.5 seconds
    gpiod_pin_set_callback(pin, GPIOD_PIN_EDGE_BOTH, gpiod_pin_callback, (void *) 4);

    // Start the callback
    gpiod_pin_enable(pin);

    // Main loop
    while (1) {
        // Sleep for 0.5 seconds
        usleep(500000);

        // Print the current state of the pin
        gpiod_pin_get_value(pin, 0, NULL);
        printf("Pin 4: %d\n", gpiod_pin_get_value(pin, 0));
    }

    // Clean up
    gpiod_pin_disable(pin);
    gpiod_pin_close(pin);
    gpiod_device_close(dev);
    gpiod_exit();

    return 0;
}

