#include <stdio.h>
#include <stdlib.h>
#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    gpiod_init();

    // Open the GPIO device
    gpiod_device *dev = gpiod_device_open("gpio-4", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        gpiod_exit();
        return 1;
    }

    // Get the GPIO pin
    gpiod_gpio *gpio = gpiod_gpio_open(dev, 4);
    if (!gpio) {
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the initial state to LOW
    gpiod_gpio_set_value(gpio, 0);

    // Main loop
    while (1) {
        // Print the current state
        printf("%d\n", gpiod_gpio_get_value(gpio));

        // Wait for 50 milliseconds
        usleep(50000);

        // Toggle the state
        gpiod_gpio_set_value(gpio, 1 - gpiod_gpio_get_value(gpio));
    }

    // Clean up
    gpiod_gpio_close(gpio);
    gpiod_device_close(dev);
    gpiod_exit();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <termios.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <pigpio.h>

#define BAUDRATE 9600
#define PORT 0
#define BUFFER_SIZE 1024

int main() {
    int fd, gpio, pin;
    struct termios oldt, newt;
    struct termios tty;
    struct sigaction sa;
    int bytes_read;

    // Initialize GPIO
    if (gpio = pigpio_init()) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    // Open serial port
    if ((fd = open("/dev/ttyS0", O_RDWR | O_NOCTTY | O_NONBLOCK)) < 0) {
        printf("Failed to open serial port\n");
        pigpio_close(gpio);
        return 1;
    }

    // Set serial port parameters
    cfsetispeed(&tty, BAUDRATE);
    cfsetispeed(&tty, BAUDRATE);
    tcflush(fd, TCIFLUSH);
    tcgetattr(fd, &tty);
    memcpy(&oldt, &tty, sizeof(oldt));
    cfsetispeed(&newt, BAUDRATE);
    cfsetospeed(&newt, BAUDRATE);
    tcflush(fd, TCIFLUSH);
    memcpy(&tty, &newt, sizeof(tty));
    if (tcsetattr(fd, TCSANOW, &tty) < 0) {
        printf("Failed to set serial port parameters\n");
        close(fd);
        pigpio_close(gpio);
        return 1;
    }

    // Set serial port to non-blocking
    if (tcgetattr(fd, &tty) < 0) {
        printf("Failed to get serial port attributes\n");
        close(fd);
        pigpio_close(gpio);
        return 1;
    }
    tty.c_lflag &= ~ICANON;
    tty.c_lflag &= ~ECHO;
    if (tcsetattr(fd, TCSANOW, &tty) < 0) {
        printf("Failed to set serial port to non-blocking\n");
        close(fd);
        pigpio_close(gpio);
        return 1;
    }

    // Set up signal handler
    sa.sa_handler = SIG_DFL;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGIO, &sa, NULL) < 0) {
        printf("Failed to set signal handler\n");
        close(fd);
        pigpio_close(gpio);
        return 1;
    }

    // Open serial port for reading
    if ((bytes_read = read(fd, NULL, BUFFER_SIZE)) < 0) {
        printf("Failed to open serial port for reading\n");
        close(fd);
        pigpio_close(gpio);
        return 1;
    }

    // Read from serial port
    while (1) {
        if ((bytes_read = read(fd, NULL, BUFFER_SIZE)) < 0) {
            printf("Error reading from serial port\n");
            break;
        }
        printf("%s", (char *)malloc(bytes_read));
        free((void *)malloc(bytes_read));
    }

    // Restore original serial port settings
    if (tcsetattr(fd, TCSANOW, &oldt) < 0) {
        printf("Failed to restore serial port settings\n");
    }

    // Close serial port
    if (close(fd) < 0) {
        printf("Failed to close serial port\n");
    }

    // Release GPIO
    pigpio_close(gpio);

    return 0;
}

#include <stdio.h>
