int main() {
    int fd;
    int pin = 17;
    int state = 0;
    struct timespec delay = {0, 1000};

    // Initialize libgpiod
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open the device file
    fd = open("/dev/gpiod/17", O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Set the pin to the current state
        if (gpioWrite(fd, state) < 0) {
            perror("gpioWrite");
            break;
        }

        // Check if the device is responding
        struct io_event event;
        if (ioGetEvent(fd, &event) < 0) {
            perror("ioGetEvent");
            break;
        }

        // Check if the device has changed state
        if (event.type == IO_EVENT_VALUE) {
            if (event.value != state) {
                state = event.value;
                printf("State: %d\n", state);
            }
        }

        // Sleep for the specified delay
        nanosleep(&delay, NULL);
    }

    // Release the device file
    close(fd);

    // Terminate libgpiod
    gpioTerminate();

    return 0;
}

