int main() {
    gpiod_context_t ctx;
    gpiod_gpio_t pin;
    gpiod_gpio_request_t req;
    gpiod_gpio_flags_t flags;
    gpiod_gpio_value_t value;

    // Initialize libgpiod
    if (gpiod_init(&ctx) != 0) {
        fprintf(stderr, "gpiod_init failed\n");
        return EXIT_FAILURE;
    }

    // Create a new GPIO request
    if (gpiod_gpio_request(&req, GPIO_PIN, GPIOF_INPUT) != 0) {
        fprintf(stderr, "gpiod_gpio_request failed\n");
        gpiod_exit(&ctx);
        return EXIT_FAILURE;
    }

    // Set the GPIO pin direction to output
    if (gpiod_gpio_direction(&req, GPIOF_OUTPUT) != 0) {
        fprintf(stderr, "gpiod_gpio_direction failed\n");
        gpiod_gpio_release(&req);
        gpiod_exit(&ctx);
        return EXIT_FAILURE;
    }

    // Set the GPIO pin value
    if (gpiod_gpio_value(&req, GPIO_PIN2, 1) != 0) {
        fprintf(stderr, "gpiod_gpio_value failed\n");
        gpiod_gpio_release(&req);
        gpiod_exit(&ctx);
        return EXIT_FAILURE;
    }

    // Set the GPIO pin flags
    if (gpiod_gpio_flags(&req, GPIOF_OUTPUT_HIGH) != 0) {
        fprintf(stderr, "gpiod_gpio_flags failed\n");
        gpiod_gpio_release(&req);
        gpiod_exit(&ctx);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read the GPIO pin value
        if (gpiod_gpio_value(&req, GPIO_PIN, &value) != 0) {
            fprintf(stderr, "gpiod_gpio_value failed\n");
            gpiod_gpio_release(&req);
            gpiod_exit(&ctx);
            return EXIT_FAILURE;
        }

        // Check if the value is valid
        if (value != 1) {
            fprintf(stderr, "Invalid value: %d\n", value);
            gpiod_gpio_release(&req);
            gpiod_exit(&ctx);
            return EXIT_FAILURE;
        }

        // Print the value to standard output
        printf("GPIO %d: %d\n", GPIO_PIN2, value);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Release the GPIO pin
    gpiod_gpio_release(&req);

    // Exit libgpiod
    gpiod_exit(&ctx);

    return EXIT_SUCCESS;
}

