#include <stdio.h>
#include <stdlib.h>
#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return ret;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-17", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_exit();
        return 1;
    }

    // Open the GPIO device for GPIO 18
    struct gpiod_device *dev18 = gpiod_device_open("gpio-18", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev18) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Get the GPIO handle for GPIO 17
    struct gpiod_gpio *gpio17 = gpiod_gpio_open(dev, 17);
    if (!gpio17) {
        fprintf(stderr, "gpiod_gpio_open failed\n");
        gpiod_device_close(dev18);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Get the GPIO handle for GPIO 18
    struct gpiod_gpio *gpio18 = gpiod_gpio_open(dev18, 18);
    if (!gpio18) {
        fprintf(stderr, "gpiod_gpio_open failed\n");
        gpiod_gpio_close(gpio17);
        gpiod_device_close(dev18);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set GPIO 17 to high
    ret = gpiod_gpio_set_value(gpio17, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_gpio_close(gpio18);
        gpiod_gpio_close(gpio17);
        gpiod_device_close(dev18);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set GPIO 18 to low
    ret = gpiod_gpio_set_value(gpio18, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_gpio_close(gpio18);
        gpiod_gpio_close(gpio17);
        gpiod_device_close(dev18);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Wait for 1 second
    sleep(1);

    // Set GPIO 17 to low
    ret = gpiod_gpio_set_value(gpio17, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_gpio_close(gpio18);
        gpiod_gpio_close(gpio17);
        gpiod_device_close(dev18);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set GPIO 18 to high
    ret = gpiod_gpio_set_value(gpio18, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_gpio_close(gpio18);
        gpiod_gpio_close(gpio17);
        gpiod_device_close(dev18);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Close the GPIO devices
    gpiod_gpio_close(gpio18);
    gpiod_gpio_close(gpio17);
    gpiod_device_close(dev18);
    gpiod_device_close(dev);

    // Exit
    gpiod_exit();
    return 0;
