#include <stdio.h>
#include <stdlib.h>
#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return ret;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-17", GpioLine, NULL);
    if (!dev) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_exit();
        return 1;
    }

    // Open the GPIO device for GPIO 18
    struct gpiod_device *dev18 = gpiod_device_open("gpio-18", GpioLine, NULL);
    if (!dev18) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Open the GPIO device for GPIO 27
    struct gpiod_device *dev27 = gpiod_device_open("gpio-27", GpioLine, NULL);
    if (!dev27) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_device_close(dev18);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the state of GPIO 17
    ret = gpiod_device_set_value(dev, 17, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_device_set_value failed: %d\n", ret);
        gpiod_device_close(dev18);
        gpiod_device_close(dev27);
        gpiod_exit();
        return 1;
    }

    // Set the state of GPIO 18
    ret = gpiod_device_set_value(dev18, 0, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_device_set_value failed: %d\n", ret);
        gpiod_device_close(dev);
        gpiod_device_close(dev27);
        gpiod_exit();
        return 1;
    }

    // Set the state of GPIO 27
    ret = gpiod_device_set_value(dev27, 0, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_device_set_value failed: %d\n", ret);
        gpiod_device_close(dev18);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Wait for 2 seconds
    sleep(2);

    // Clear the state of GPIO 17
    ret = gpiod_device_set_value(dev, 17, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_device_set_value failed: %d\n", ret);
        gpiod_device_close(dev18);
        gpiod_device_close(dev27);
        gpiod_exit();
        return 1;
    }

    // Clear the state of GPIO 18
    ret = gpiod_device_set_value(dev18, 0, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_device_set_value failed: %d\n", ret);
        gpiod_device_close(dev);
        gpiod_device_close(dev27);
        gpiod_exit();
        return 1;
    }

    // Clear the state of GPIO 27
    ret = gpiod_device_set_value(dev27, 0, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_device_set_value failed: %d\n", ret);
        gpiod_device_close(dev18);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Close the GPIO devices
    gpiod_device_close(dev27);
    gpiod_device_close(dev18);
    gpiod_device_close(dev);

    // Exit libgpiod
    gpiod_exit();

    return 0;
}

