#include <stdio.h>
#include <stdlib.h>
#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return ret;
    }

    // Get the device object for GPIO 2
    struct gpiod_device *dev = gpiod_device_get("gpio-2");
    if (!dev) {
        fprintf(stderr, "Failed to get device for GPIO 2\n");
        gpiod_exit();
        return 1;
    }

    // Get the direction of the device
    struct gpiod_direction direction;
    ret = gpiod_direction_get(dev, &direction);
    if (ret < 0) {
        fprintf(stderr, "gpiod_direction_get failed: %d\n", ret);
        gpiod_device_put(dev);
        gpiod_exit();
        return 1;
    }

    // Check if the device is active
    if (direction.active) {
        fprintf(stderr, "GPIO 2 is already active\n");
        gpiod_device_put(dev);
        gpiod_exit();
        return 1;
    }

    // Set the direction of the device
    ret = gpiod_direction_set(dev, direction);
    if (ret < 0) {
        fprintf(stderr, "gpiod_direction_set failed: %d\n", ret);
        gpiod_device_put(dev);
        gpiod_exit();
        return 1;
    }

    // Set the value of the device
    struct gpiod_value value;
    value.value = 1;
    ret = gpiod_value_set(dev, &value);
    if (ret < 0) {
        fprintf(stderr, "gpiod_value_set failed: %d\n", ret);
        gpiod_device_put(dev);
        gpiod_exit();
        return 1;
    }

    // Wait for 1 second
    sleep(1);

    // Get the current value of the device
    ret = gpiod_value_get(dev, &value);
    if (ret < 0) {
        fprintf(stderr, "gpiod_value_get failed: %d\n", ret);
        gpiod_device_put(dev);
        gpiod_exit();
        return 1;
    }

    // Check if the value is 1
    if (value.value != 1) {
        fprintf(stderr, "Expected value 1, got %d\n", value.value);
        gpiod_device_put(dev);
        gpiod_exit();
        return 1;
    }

    // Release the device
    gpiod_device_put(dev);

    // Wait for the interrupt to be released
    while (gpiod_get_interrupt(dev) != 0);

    // Exit
    gpiod_exit();
    return 0;
}

