#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x44
#define I2C_REG 0x00

int main() {
    int fd;
    void* mem;
    unsigned char reg;
    int ret;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address
    ret = ioctl(fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Map I2C memory
    mem = mmap(NULL, 256, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mem == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return 1;
    }

    // Read measurement
    ret = ioctl(fd, I2C_SMBUS_READ, &reg);
    if (ret < 0) {
        perror("ioctl");
        munmap(mem, 256);
        close(fd);
        return 1;
    }

    // Print measurement
    printf("%02x\n", reg);

    // Unmap and close I2C device
    munmap(mem, 256);
    close(fd);

    return 0;
}

