#define BAUDRATE 9600
#define PORT 0
#define BUFFER_SIZE 1024

int main() {
    int fd, gpio_fd;
    struct termios oldt, newt;
    struct termios tty;
    struct sigaction sa;
    int bytes_read;
    char buffer[BUFFER_SIZE];
    int timeout = 1;
    int timeout_fd = -1;

    // Initialize GPIO
    if (gpio_init() != 0) {
        perror("gpio_init");
        return 1;
    }

    // Open serial port
    fd = open("/dev/ttyUSB0", O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        gpio_cleanup();
        return 1;
    }

    // Set up serial port
    tcgetattr(fd, &oldt);
    tcgetattr(fd, &newt);
    cfsetispeed(&newt, BAUDRATE);
    cfsetospeed(&newt, BAUDRATE);
    tcsetattr(fd, TCSANOW, &newt);

    // Set up timeout
    if (ioctl(fd, FIONREAD, &timeout) == -1) {
        perror("ioctl");
        close(fd);
        gpio_cleanup();
        return 1;
    }

    // Set up signal handler
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGPIPE, &sa, NULL) == -1) {
        perror("sigaction");
        close(fd);
        gpio_cleanup();
        return 1;
    }

    // Set up interrupt
    gpio_fd = gpioGetFd(PORT);
    if (gpio_fd == -1) {
        perror("gpioGetFd");
        close(fd);
        gpio_cleanup();
        return 1;
    }

    while (1) {
        // Read from serial port
        if (read(fd, buffer, BUFFER_SIZE) == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // Timeout, check for interrupt
                if (gpioRead(PORT) == 0) {
                    // Interrupt detected, exit
                    break;
                }
                continue;
            } else {
                perror("read");
                close(fd);
                gpio_cleanup();
                return 1;
            }
        }

        // Print to standard output
        printf("%s", buffer);

        // Check for interrupt
        if (gpioRead(PORT) == 0) {
            // Interrupt detected, exit
            break;
        }
    }

    // Release resources
    close(fd);
    gpioRelease(gpio_fd);
    gpio_cleanup();

    return 0;
