int main() {
    // Initialize libgpiod
    gpiod_init();

    // Open the GPIO device
    gpiod_device *dev = gpiod_device_open("gpio-2", GPIOF_READ | GPIOF_WRITE);
    if (!dev) {
        perror("Failed to open GPIO device");
        return 1;
    }

    // Get the GPIO pin
    gpiod_pin *pin = gpiod_pin_get(dev, GPIOF_READ | GPIOF_WRITE, GPIOF_DIR, GPIOF_INPUT, GPIOF_EDGE_NONE, GPIOF_OPEN_DRAIN, GPIOF_OUTPUT, GPIOF_HIGH, GPIOF_HIGH, GPIOF_HIGH);
    if (!pin) {
        perror("Failed to get GPIO pin");
        gpiod_device_close(dev);
        return 1;
    }

    // Set the initial state
    gpiod_pin_set_value(pin, GPIOF_HIGH);

    // Start the main loop
    while (CYCLE_COUNT--) {
        // Check for errors
        if (gpiod_pin_get_value(pin) != GPIOF_HIGH) {
            printf("Invalid state: %d\n", gpiod_pin_get_value(pin));
            break;
        }

        // Set the state
        gpiod_pin_set_value(pin, GPIOF_HIGH);

        // Sleep for 1 second
        usleep(1000000);

        // Set the state to low
        gpiod_pin_set_value(pin, GPIOF_LOW);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Release the pin
    gpiod_pin_release(pin);

    // Close the GPIO device
    gpiod_device_close(dev);

    // Finalize libgpiod
    gpiod_finalize();

    return 0;
}

