    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return ret;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-5", GpioDirectionOutput);
    if (!dev) {
        fprintf(stderr, "Failed to open GPIO device\n");
        gpiod_exit();
        return 1;
    }

    // Open the GPIO device for GPIO 17
    struct gpiod_device *dev17 = gpiod_device_open("gpio-17", GpioDirectionOutput);
    if (!dev17) {
        fprintf(stderr, "Failed to open GPIO device\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Open the GPIO device for GPIO 24
    struct gpiod_device *dev24 = gpiod_device_open("gpio-24", GpioDirectionOutput);
    if (!dev24) {
        fprintf(stderr, "Failed to open GPIO device\n");
        gpiod_device_close(dev17);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the initial state of GPIO 5, 17, and 24
    ret = gpiod_device_set_value(dev, 5, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 5: %d\n", ret);
        gpiod_device_close(dev24);
        gpiod_device_close(dev17);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }
    ret = gpiod_device_set_value(dev17, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 17: %d\n", ret);
        gpiod_device_close(dev24);
        gpiod_device_close(dev17);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }
    ret = gpiod_device_set_value(dev24, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 24: %d\n", ret);
        gpiod_device_close(dev24);
        gpiod_device_close(dev17);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Main loop
    while (1) {
        // Set the state of GPIO 5, 17, and 24
        ret = gpiod_device_set_value(dev, 5, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO 5: %d\n", ret);
            gpiod_device_close(dev24);
            gpiod_device_close(dev17);
            gpiod_device_close(dev);
            gpiod_exit();
            return 1;
        }
        ret = gpiod_device_set_value(dev17, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO 17: %d\n", ret);
            gpiod_device_close(dev24);
            gpiod_device_close(dev17);
            gpiod_device_close(dev);
            gpiod_exit();
            return 1;
        }
        ret = gpiod_device_set_value(dev24, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO 24: %d\n", ret);
            gpiod_device_close(dev24);
            gpiod_device_close(dev17);
            gpiod_device_close(dev);
            gpiod_exit();
            return 1;
        }

        // Print the state of GPIO 5, 17, and 24
        printf("GPIO 5: %d, GPIO 17: %d, GPIO 24: %d\n", gpiod_device_get_value(dev, 5), gpiod_device_get_value(dev17, 1), gpiod_device_get_value(dev24, 1));

        // Sleep for 0.2 seconds
        usleep(200000);

        // Check if the device is absent
        if (gpiod_device_is_absent(dev)) {
            fprintf(stderr, "Device absent\n");
            gpiod_device_close(dev24);
            gpiod_device_close(dev17);
            gpiod_device_close(dev);
            gpiod_exit();
            return 1;
        }
    }

    // Release the hardware
    gpiod_device_close(dev24);
    gpiod_device_close(dev17);
    gpiod_device_close(dev);

    // Exit cleanly
    gpiod_exit();
    return 0;
}

#include <stdio.h>
