        return 1;
    }

    // Create GPIO devices
    if (gpiod_gpio_new(&pin17, ctx, GPIO_DIR_OUT, GPIO_VALUE_NONE, 17) != 0) {
        fprintf(stderr, "Failed to create GPIO device for pin 17\n");
        gpiod_context_free(ctx);
        return 1;
    }
    if (gpiod_gpio_new(&pin22, ctx, GPIO_DIR_OUT, GPIO_VALUE_NONE, 22) != 0) {
        fprintf(stderr, "Failed to create GPIO device for pin 22\n");
        gpiod_gpio_delete(pin17);
        gpiod_context_free(ctx);
        return 1;
    }
    if (gpiod_gpio_new(&pin27, ctx, GPIO_DIR_OUT, GPIO_VALUE_NONE, 27) != 0) {
        fprintf(stderr, "Failed to create GPIO device for pin 27\n");
        gpiod_gpio_delete(pin22);
        gpiod_gpio_delete(pin17);
        gpiod_context_free(ctx);
        return 1;
    }

    // Request GPIO devices
    if (gpiod_gpio_request(pin17, &req17) != 0) {
        fprintf(stderr, "Failed to request GPIO device for pin 17\n");
        gpiod_gpio_delete(pin27);
        gpiod_gpio_delete(pin22);
        gpiod_gpio_delete(pin17);
        gpiod_context_free(ctx);
        return 1;
    }
    if (gpiod_gpio_request(pin22, &req22) != 0) {
        fprintf(stderr, "Failed to request GPIO device for pin 22\n");
        gpiod_gpio_request_release(req17);
        gpiod_gpio_delete(pin27);
        gpiod_gpio_delete(pin22);
        gpiod_gpio_delete(pin17);
        gpiod_context_free(ctx);
        return 1;
    }
    if (gpiod_gpio_request(pin27, &req27) != 0) {
        fprintf(stderr, "Failed to request GPIO device for pin 27\n");
        gpiod_gpio_request_release(req22);
        gpiod_gpio_request_release(req17);
        gpiod_gpio_delete(pin27);
        gpiod_gpio_delete(pin22);
        gpiod_gpio_delete(pin17);
        gpiod_context_free(ctx);
        return 1;
    }

    // Set initial values
    gpiod_gpio_flags_set(req17, GPIO_FLAG_INIT);
    gpiod_gpio_flags_set(req22, GPIO_FLAG_INIT);
    gpiod_gpio_flags_set(req27, GPIO_FLAG_INIT);
    gpiod_gpio_value_set(req17, 0);
    gpiod_gpio_value_set(req22, 0);
    gpiod_gpio_value_set(req27, 0);

    // Main loop
    while (1) {
        // Get current values
        gpiod_gpio_flags_get(req17, &flags17);
        gpiod_gpio_flags_get(req22, &flags22);
        gpiod_gpio_flags_get(req27, &flags27);
        gpiod_gpio_value_get(req17, &value17);
        gpiod_gpio_value_get(req22, &value22);
        gpiod_gpio_value_get(req27, &value27);

        // Print current values
        printf("Pin 17: %d\n", value17);
        printf("Pin 22: %d\n", value22);
        printf("Pin 27: %d\n", value27);

        // Toggle values
        gpiod_gpio_value_set(req17, 1);
        gpiod_gpio_value_set(req22, 1);
        gpiod_gpio_value_set(req27, 1);

        // Sleep for 0.1 seconds
        sleep(0.1);
    }

    // Release GPIO devices
    gpiod_gpio_request_release(req27);
    gpiod_gpio_request_release(req22);
    gpiod_gpio_request_release(req17);

    // Delete GPIO devices
    gpiod_gpio_delete(pin27);
    gpiod_gpio_delete(pin22);
    gpiod_gpio_delete(pin17);

    // Free gpiod context
    gpiod_context_free(ctx);

    return 0;
}

