#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pigpio.h>
#include <w1-gpio.h>

#define GPIO_W1_SDA 4
#define GPIO_W1_SCL 17
#define GPIO_W1_GND 18

int main() {
    int fd;
    int ret;
    struct w1_slave *w1;
    struct w1_node *node;
    struct w1_master_config config;
    struct w1_master_config *config_ptr;
    struct w1_master_config *config_ptr2;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up GPIO for 1-Wire
    if (gpioSetMode(GPIO_W1_SDA, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO_W1_SCL, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO_W1_GND, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Open sysfs-w1 device
    fd = open("/sys/class/w1_slave/w1_slave_ds18b20", O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Read and parse configuration
    if (read(fd, &config, sizeof(config)) != sizeof(config)) {
        perror("read");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (config.config != 0x44) {
        printf("Invalid device configuration\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Create a w1-master object
    w1 = w1MasterCreate(&config);
    if (w1 == NULL) {
        perror("w1MasterCreate");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Get the node
    node = w1GetNode(w1);
    if (node == NULL) {
        perror("w1GetNode");
        w1MasterDelete(w1);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read temperature
        ret = w1ReadNode(node, &config_ptr);
        if (ret < 0) {
            perror("w1ReadNode");
            w1MasterDelete(w1);
            close(fd);
            gpioTerminate();
            return 1;
        }
        if (config_ptr->valid == 0) {
            printf("Invalid reading\n");
            w1MasterDelete(w1);
            close(fd);
            gpioTerminate();
            return 1;
        }
        printf("%d\n", config_ptr->temp);

        // Wait 5 seconds
        sleep(5);
    }

    // Clean up
    w1MasterDelete(w1);
    close(fd);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x40
#define I2C_TIMEOUT 1000
#define BUFFER_SIZE 6

int main() {
    int fd;
    void* buffer;
    int bytes_read;
    int i;
    int valid;
    int error = 0;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("set I2C address");
        close(fd);
        return 1;
    }

    // Map I2C memory
    buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return 1;
    }

    while (1) {
        // Read from I2C
        bytes_read = read(fd, buffer, BUFFER_SIZE);
        if (bytes_read < 0) {
            perror("read");
            error = 1;
            break;
        }

        // Check for errors
        if (bytes_read < 2) {
            error = 1;
            break;
        }

        // Check for valid reading
        if (buffer[0] != 0x10 || buffer[1] != 0x00) {
            error = 1;
            break;
        }

        // Extract temperature and humidity
        int16_t temperature = (buffer[2] << 8) | buffer[3];
        int16_t humidity = (buffer[4] << 8) | buffer[5];

        // Print reading
