#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_DATA_REG 0x32

int main() {
    int fd;
    void* mem;
    unsigned char data[6];
    int i2c_file;
    struct i2c_client *client;
    struct i2c_dev *dev;
    struct i2c_msg msg;
    struct i2c_file *file;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Get I2C device handle
    i2c_file = fd;
    client = i2c_get_client(i2c_file);
    if (!client) {
        perror("i2c_get_client");
        close(fd);
        return 1;
    }

    // Get I2C device handle
    dev = i2c_get_device(client, ADXL345_ADDRESS);
    if (!dev) {
        perror("i2c_get_device");
        close(fd);
        i2c_release_client(client);
        return 1;
    }

    // Map I2C memory
    mem = mmap(NULL, 256, PROT_READ | PROT_WRITE, MAP_SHARED, i2c_file, 0);
    if (mem == MAP_FAILED) {
        perror("mmap");
        close(fd);
        i2c_release_device(dev);
        i2c_release_client(client);
        return 1;
    }

    while (1) {
        // Read data from ADXL345
        msg.msg_type = I2C_MMSG_READ;
        msg.msg_flags = 0;
        msg.buf = data;
        msg.len = 6;
        msg.addr = ADXL345_ADDRESS;

        if (i2c_master_send(client, &msg) < 0) {
            perror("i2c_master_send");
            break;
        }

        if (i2c_master_recv(client, &msg) < 0) {
            perror("i2c_master_recv");
            break;
        }

        // Print data
        printf("%02x %02x %02x %02x %02x %02x %02x\n",
               data[0], data[1], data[2], data[3], data[4], data[5]);

        // Wait for 0.1 seconds
        usleep(100000);
    }

    // Release resources
    munmap(mem, 256);
    close(fd);
    i2c_release_device(dev);
    i2c_release_client(client);

    return 0;
}

