int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Define PWM pins
    const int pin1 = 17;
    const int pin2 = 22;
    const int pin3 = 27;

    // Check if pins are available
    if (gpioGetPinMode(pin1, GPIO_MODE_PWM) < 0) {
        fprintf(stderr, "Error: GPIO %d is not available\n", pin1);
        gpioTerminate();
        return 1;
    }
    if (gpioGetPinMode(pin2, GPIO_MODE_PWM) < 0) {
        fprintf(stderr, "Error: GPIO %d is not available\n", pin2);
        gpioTerminate();
        return 1;
    }
    if (gpioGetPinMode(pin3, GPIO_MODE_PWM) < 0) {
        fprintf(stderr, "Error: GPIO %d is not available\n", pin3);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    const int frequency = 1000; // Hz
    const int duty_cycle = 50; // 50% duty cycle
    const int period = 10000; // 10ms period
    if (gpioSet PWM(pin1, frequency, duty_cycle, period) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d: %s\n", pin1, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioSet PWM(pin2, frequency, duty_cycle, period) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d: %s\n", pin2, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioSet PWM(pin3, frequency, duty_cycle, period) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d: %s\n", pin3, strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Set PWM values
        gpioSet PWM(pin1, frequency, 0, period);
        gpioSet PWM(pin2, frequency, 0, period);
        gpioSet PWM(pin3, frequency, 0, period);

        // Sleep for 0.5 seconds
        sleep(0.5);

        // Set PWM values
        gpioSet PWM(pin1, frequency, duty_cycle, period);
        gpioSet PWM(pin2, frequency, duty_cycle, period);
        gpioSet PWM(pin3, frequency, duty_cycle, period);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

