int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-18", GpioDirectionOutput);
    if (!dev) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Open the GPIO device for GPIO 21
    struct gpiod_device *dev21 = gpiod_device_open("gpio-21", GpioDirectionOutput);
    if (!dev21) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Open the GPIO device for GPIO 22
    struct gpiod_device *dev22 = gpiod_device_open("gpio-22", GpioDirectionOutput);
    if (!dev22) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_device_close(dev21);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set GPIO 18 to high
    ret = gpiod_device_set_value(dev, 18, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_device_set_value failed: %d\n", ret);
        gpiod_device_close(dev22);
        gpiod_device_close(dev21);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set GPIO 21 to high
    ret = gpiod_device_set_value(dev21, 1, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_device_set_value failed: %d\n", ret);
        gpiod_device_close(dev22);
        gpiod_device_close(dev21);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set GPIO 22 to high
    ret = gpiod_device_set_value(dev22, 1, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_device_set_value failed: %d\n", ret);
        gpiod_device_close(dev22);
        gpiod_device_close(dev21);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Wait for 2 seconds
    sleep(2);

    // Set GPIO 18 to low
    ret = gpiod_device_set_value(dev, 18, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_device_set_value failed: %d\n", ret);
        gpiod_device_close(dev22);
        gpiod_device_close(dev21);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set GPIO 21 to low
    ret = gpiod_device_set_value(dev21, 1, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_device_set_value failed: %d\n", ret);
        gpiod_device_close(dev22);
        gpiod_device_close(dev21);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set GPIO 22 to low
    ret = gpiod_device_set_value(dev22, 1, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_device_set_value failed: %d\n", ret);
        gpiod_device_close(dev22);
        gpiod_device_close(dev21);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Close the GPIO devices
    gpiod_device_close(dev22);
    gpiod_device_close(dev21);
    gpiod_device_close(dev);

    // Exit
    gpiod_exit();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/v4l2/v4l2.h>

#define CAMERA_DEVICE "/dev/video0"
#define IMAGE_FILE "image.jpg"

int main() {
    int fd, ret;
    struct v4l2_buffer buf;
    struct v4l2_image img;
    struct v4l2_format fmt;
    pigpio gpio;
    pigpio_init(gpio);
    pigpio_set_mode(gpio, PI_INPUT, 17); // enable camera trigger

    if (pigpio_get(gpio, PI_INPUT, 17) < 0) {
        printf("Error: unable to access camera trigger pin\n");
        return 1;
    }

    if ((ret = pigpio_wait(gpio, PI_INPUT, 17, 1000)) < 0) {
        printf("Error: unable to wait for camera trigger\n");
        return 1;
    }

    if ((ret = pigpio_get(gpio, PI_INPUT, 17) < 0) {
        printf("Error: unable to access camera trigger pin\n");
        return 1;
    }

    if ((ret = pigpio_release(gpio, PI_INPUT, 17)) < 0) {
        printf("Error: unable to release camera trigger pin\n");
        return 1;
    }

    if ((fd = open(CAMERA_DEVICE, O_RDWR)) < 0) {
        printf("Error: unable to open camera device\n");
        return 1;
    }

    if ((ret = ioctl(fd, V4L2_QUERY Capabilities, &fmt)) < 0) {
        printf("Error: unable to query camera capabilities\n");
        return 1;
    }

    if (fmt.image_width == 0 || fmt.image_height == 0 || fmt.image_bytesperline == 0) {
        printf("Error: camera device is not available\n");
        return 1;
    }

    if ((ret = mmap(NULL, fmt.image_bytesperline * fmt.image_height, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0)) < 0) {
        printf("Error: unable to map camera memory\n");
        return 1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_IMAGE_MMAP;
    buf.image_length = fmt.image_bytesperline * fmt.image_height;
    buf.image_size = fmt.image_bytesperline * fmt.image_height;
    buf.image_start = mmap(NULL, fmt.image_bytesperline * fmt.image_height, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buf.image_start == MAP_FAILED) {
        printf("Error: unable to map camera image buffer\n");
        return 1;
    }

    if ((ret = ioctl(fd, V4L2_GBUF, &buf)) < 0) {
        printf("Error: unable to get camera image buffer\n");
        return 1;
    }

    if (buf.image_length != fmt.image_bytesperline * fmt.image_height) {
        printf("Error: camera image buffer size mismatch\n");
        return 1;
    }

    if (buf.image_start == MAP_FAILED) {
        printf("Error: unable to get camera image buffer\n");
        return 1;
    }

    if (buf.image_start) {
        unsigned char *p = buf.image_start;
        for (int i = 0; i < buf.image_length; i += 3) {
            unsigned char r = *p++;
            unsigned char g = *p++;
            unsigned char b = *p++;
            printf("%02x%02x%02x ", r, g, b);
        }
        printf("\n");
    }

    if ((ret = close(fd)) < 0) {
        printf("Error: unable to close camera device\n");
        return 1;
    }

    if ((ret = munmap(buf.image_start, buf.image_length)) < 0) {
        printf("Error: unable to unmap camera image buffer\n");
        return 1;
    }

    if ((ret = pigpio_release(gpio, PI_INPUT, 17)) < 0) {
        printf("Error: unable to release camera trigger pin\n");
        return 1;
    }

    if ((ret = pigpio_close(gpio)) < 0) {
        printf("Error: unable to close pigpio\n");
        return 1;
    }

    if ((ret = unlink(IMAGE_FILE)) < 0) {
        printf("Error: unable to remove image file\n");
        return 1;
    }

    return 0;
}

