// Define the GPIO pin number
#define GPIO_PIN 18

// Define the number of pixels in the strip
#define NUM_PIXELS 60

// Define the colour values
#define RED 0xFF0000
#define GREEN 0x00FF00
#define BLUE 0x0000FF

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %d\n", gpioInitialise());
        return 1;
    }

    // Set up the GPIO pin as an output
    if (gpioMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO pin %d as output: %d\n", GPIO_PIN, gpioMode(GPIO_PIN));
        gpioTerminate();
        return 1;
    }

    // Set up the GPIO pin as a PWM output
    if (gpioPWMConfig(GPIO_PIN, PI PWM, 50000) < 0) {
        fprintf(stderr, "Error configuring GPIO pin %d as PWM output: %d\n", GPIO_PIN, gpioPWMConfig(GPIO_PIN, PI PWM, 50000));
        gpioTerminate();
        return 1;
    }

    // Define the colour values
    uint32_t colours[] = {RED, GREEN, BLUE};

    // Main loop
    while (1) {
        // Clear the strip
        for (int i = 0; i < NUM_PIXELS; i++) {
            gpioWrite(GPIO_PIN, i, 0);
        }

        // Set the colours
        for (int i = 0; i < NUM_PIXELS; i++) {
            uint32_t colour = colours[i % 3];
            gpioWrite(GPIO_PIN, i, (colour << 16) | (colour << 8) | colour);
        }

        // Delay for 10ms
        usleep(10000);

        // Check for interrupt
        if (gpioRead(GPIO_PIN) & (1 << GPIO_PIN)) {
            fprintf(stderr, "Error: GPIO pin %d is busy\n", GPIO_PIN);
            gpioTerminate();
            return 1;
        }
    }

    // Release the GPIO pin
    gpioTerminate();

    return 0;
}

