#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/v4l2/v4l2.h>

#define BUFFER_SIZE 1024 * 1024
#define FILE_NAME "image.jpg"

int main() {
    int fd, ret;
    struct v4l2_buffer buf;
    struct v4l2_image img;
    struct v4l2_format fmt;
    pigpio_handler_t handler;
    pigpio_t *gpio;
    void *mem;

    // Initialize pigpio
    if (pigpio_init() < 0) {
        perror("pigpio_init");
        return 1;
    }

    // Open the camera
    gpio = pigpio_open(17, PI_INPUT, &handler);
    if (gpio == -1) {
        perror("pigpio_open");
        pigpio_close(gpio);
        return 1;
    }

    // Get the camera format
    ret = pigpio_get_value(gpio, 0, &fmt);
    if (ret != 0) {
        pigpio_close(gpio);
        pigpio_unlink_handler(handler);
        return 1;
    }

    // Open the v4l2 device
    fd = open("/dev/video0", O_RDWR);
    if (fd == -1) {
        pigpio_close(gpio);
        pigpio_unlink_handler(handler);
        return 1;
    }

    // Map the v4l2 device
    mem = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mem == MAP_FAILED) {
        close(fd);
        pigpio_close(gpio);
        pigpio_unlink_handler(handler);
        return 1;
    }

    // Set the v4l2 format
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_IMAGE;
    buf.image_length = BUFFER_SIZE;
    buf.image_size = BUFFER_SIZE;
    buf.image_field = V4L2_IMAGE_FIELD_LEFT;
    buf.image_width = fmt.width;
    buf.image_height = fmt.height;
    buf.image_plane = 0;
    buf.image_format = fmt.fmt;
    buf.image_crop_left = 0;
    buf.image_crop_top = 0;
    buf.image_crop_right = 0;
    buf.image_crop_bottom = 0;
    buf.image_dither = 0;
    buf.image_colorspace = V4L2_COLORSPACE_SRGB;
    buf.image_encoding = V4L2_ENCODING_YUYV422;
    buf.image_field = V4L2_IMAGE_FIELD_LEFT;
    buf.image_plane = 0;
    buf.image_rotation = 0;
    buf.image_scale = 1;
    buf.image_shift = 0;

    ret = ioctl(fd, V4L2_CTRL, &buf);
    if (ret != 0) {
        munmap(mem, BUFFER_SIZE);
        close(fd);
        pigpio_close(gpio);
        pigpio_unlink_handler(handler);
        return 1;
    }

    // Capture the image
    ret = ioctl(fd, V4L2_MMAP, &buf);
    if (ret != 0) {
        munmap(mem, BUFFER_SIZE);
        close(fd);
        pigpio_close(gpio);
        pigpio_unlink_handler(handler);
        return 1;
    }

    // Save the image
    ret = write(fd, mem, BUFFER_SIZE);
    if (ret != BUFFER_SIZE) {
        munmap(mem, BUFFER_SIZE);
        close(fd);
        pigpio_close(gpio);
        pigpio_unlink_handler(handler);
        return 1;
    }

    munmap(mem, BUFFER_SIZE);
    close(fd);

    // Repeat
    while (1) {
        // Wait for 0.05 seconds
        usleep(50000);

        // Capture the image
        ret = ioctl(fd, V4L2_MMAP, &buf);
        if (ret != 0) {
            pigpio_close(gpio);
            pigpio_unlink_handler(handler);
            return 1;
        }

        // Save the image
        ret = write(fd, mem, BUFFER_SIZE);
        if (ret != BUFFER_SIZE) {
            pigpio_close(gpio);
            pigpio_unlink_handler(handler);
            return 1;
        }

        munmap(mem, BUFFER_SIZE);
    }

    // Release the hardware
    pigpio_close(gpio);
    pigpio_unlink_handler(handler);

    return 0;
}

