void init_display() {
    // Open the I2C device
    display.fd = open("/dev/i2c-1", O_RDWR);
    if (display.fd == -1) {
        perror("Failed to open I2C device");
        exit(1);
    }

    // Set the I2C address
    if (ioctl(display.fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("Failed to set I2C address");
        exit(1);
    }

    // Initialize the display
    if (ioctl(display.fd, I2C_SLAVE, I2C_ADDRESS_2) == -1) {
        perror("Failed to initialize display");
        exit(1);
    }

    // Initialize the GPIO pins
    gpio.rs = 17;
    gpio.en = 23;
    gpio.d4 = 24;
    gpio.d5 = 25;
    gpio.d6 = 26;
    gpio.d7 = 27;

    // Set the GPIO pins as output
    if (gpioInitialise(gpio.rs, gpio.en, gpio.d4, gpio.d5, gpio.d6, gpio.d7) == -1) {
        perror("Failed to set GPIO pins");
        exit(1);
    }
}

// Function to clear the display
void clear_display() {
    // Send the clear command
    if (write(display.fd, "\x00\x00", 2) == -1) {
        perror("Failed to send clear command");
        exit(1);
    }
}

// Function to write to the display
void write_to_display(const char *str) {
    // Send the command to start writing
    if (write(display.fd, "\x01", 1) == -1) {
        perror("Failed to send start command");
        exit(1);
    }

    // Write the string
    if (write(display.fd, str, strlen(str)) == -1) {
        perror("Failed to write to display");
        exit(1);
    }

    // Send the command to stop writing
    if (write(display.fd, "\x00", 1) == -1) {
        perror("Failed to send stop command");
        exit(1);
    }
}

