static int gpiod_event_handler(struct gpiod_device *dev, struct gpiod_event *event)
{
    // Check if the event is a change event
    if (event->type == GPIOD_EVENT_CHANGE)
    {
        // Get the new value of the sensor
        int value = event->value;

        // Check if the value is within the valid range
        if (value < MIN_VALUE || value > MAX_VALUE)
        {
            // Log an error and return
            syslog(LOG_ERR, "Invalid sensor value: %d", value);
            return 0;
        }

        // Publish the reading to MQTT
        if (mosquitto_publish(mosq, MQTT_TOPIC, "%d", &value) != MOSQ_ERR_NO_ERROR)
        {
            // Log an error and return
            syslog(LOG_ERR, "Failed to publish to MQTT: %s", mosquitto_last_error(mosq));
            return 0;
        }

        // Log the reading
        syslog(LOG_INFO, "Published temperature reading: %d", value);
    }

