            continue;
        }

        // Publish the reading to MQTT
        if (mosquitto_publish(mosq, MQTT_TOPIC, "%d", &value) != MOSQ_ERR_NO_ERROR)
        {
            // Log an error and retry
            syslog(LOG_ERR, "Failed to publish to MQTT");
            sleep(0.01);
            continue;
        }

        // Log the reading
        syslog(LOG_INFO, "Published temperature reading: %d", value);
    }

    // Disconnect from the MQTT broker
    mosquitto_disconnect(mosq);

    // Free the MQTT client
    mosquitto_free(mosq);

    // Free the gpiod device
    gpiod_device_free(dev);

    // Exit cleanly
    return 0;
}

