#include <stdio.h>
#include <stdlib.h>
#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-17", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Get the GPIO handle
    struct gpiod_gpio *gpio = gpiod_device_get_gpio(dev);
    if (!gpio) {
        fprintf(stderr, "gpiod_device_get_gpio failed\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the initial state
    ret = gpiod_gpio_set_value(gpio, 17, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set up the event handler
    struct gpiod_event_handler eh;
    eh.callback = gpiod_gpio_callback;
    eh.data = gpio;
    eh.flags = GPIOD_EVENT_EDGE_BOTH;
    eh.callback_data = NULL;
    ret = gpiod_gpio_set_event_handler(gpio, 17, &eh);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_event_handler failed: %d\n", ret);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Print the current state
        ret = gpiod_gpio_get_value(gpio, 17);
        if (ret < 0) {
            fprintf(stderr, "gpiod_gpio_get_value failed: %d\n", ret);
            gpiod_gpio_close(gpio);
            gpiod_device_close(dev);
            gpiod_exit();
            return EXIT_FAILURE;
        }
        printf("%d\n", ret);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpiod_gpio_close(gpio);
    gpiod_device_close(dev);
    gpiod_exit();
    return EXIT_SUCCESS;
}

