        munmap(map, 1);
        close(fd_map);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Unmap the file descriptor
    munmap(map, 1);

    // Close the file descriptor
    close(fd_map);

    // Initialize the MQTT client
    struct mosquitto *mosq;
    mosq = mosquitto_init(MQTT_BROKER, MQTT_PORT, MQTT_CLIENT_ID, NULL, NULL);
