int readI2C(int fd, unsigned char* buf, int len) {
    unsigned char ack;
    int ret;

    // Send start condition
    ret = write(fd, &ack, 1);
    if (ret < 1) {
        return ret;
    }

    // Send address
    ret = write(fd, &I2C_ADDRESS, 1);
    if (ret < 1) {
        return ret;
    }

    // Send read
    ret = write(fd, &0x00, 1);
    if (ret < 1) {
        return ret;
    }

    // Wait for read
    usleep(I2C_TIMEOUT * 1000);

    // Send stop condition
    ret = write(fd, &ack, 1);
    if (ret < 1) {
        return ret;
    }

    // Read data
    ret = read(fd, buf, len);
    if (ret < len) {
        return ret;
    }

    return ret;
}

