        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }

    // Set PWM duty cycle
    const int dutyCycle = 50; // 50% duty cycle
    if (gpioPWMWrite(gpio2, dutyCycle, resolution) < 0) {
        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }
    if (gpioPWMWrite(gpio3, dutyCycle, resolution) < 0) {
        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }
    if (gpioPWMWrite(gpio18, dutyCycle, resolution) < 0) {
        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }
    if (gpioPWMWrite(gpio23, dutyCycle, resolution) < 0) {
        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }
    if (gpioPWMWrite(gpio24, dutyCycle, resolution) < 0) {
        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }

    // Sleep for 1 second
    sleep(1);

    // Release PWM
    if (gpioPWMWrite(gpio2, 0, resolution) < 0) {
        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }
    if (gpioPWMWrite(gpio3, 0, resolution) < 0) {
        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }
    if (gpioPWMWrite(gpio18, 0, resolution) < 0) {
        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }
    if (gpioPWMWrite(gpio23, 0, resolution) < 0) {
        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }
    if (gpioPWMWrite(gpio24, 0, resolution) < 0) {
        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }

    // Release GPIOs
    if (gpioMode(gpio2, PI_INPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(gpio3, PI_INPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(gpio18, PI_INPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(gpio23, PI_INPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }
    if (gpioMode(gpio24, PI_INPUT) < 0) {
        perror("gpioMode");
        gpioTerminate();
        return 1;
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

