        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequencies
    int freq1 = 1000; // Hz
    int freq2 = 1000; // Hz
    int freq3 = 1000; // Hz
    if (gpioPWMWrite(pin1, 0, freq1) < 0) {
        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }
    if (gpioPWMWrite(pin2, 0, freq2) < 0) {
        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }
    if (gpioPWMWrite(pin3, 0, freq3) < 0) {
        perror("gpioPWMWrite");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Set PWM values
        int value1 = 128;
        int value2 = 128;
        int value3 = 128;
        if (gpioPWMWrite(pin1, value1, freq1) < 0) {
            perror("gpioPWMWrite");
            gpioTerminate();
            return 1;
        }
        if (gpioPWMWrite(pin2, value2, freq2) < 0) {
            perror("gpioPWMWrite");
            gpioTerminate();
            return 1;
        }
        if (gpioPWMWrite(pin3, value3, freq3) < 0) {
            perror("gpioPWMWrite");
            gpioTerminate();
            return 1;
        }

        // Print PWM values
        printf("Pin 17: %d\n", value1);
        printf("Pin 22: %d\n", value2);
        printf("Pin 27: %d\n", value3);

        // Sleep for 0.05 seconds
        sleep(0.05);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

