#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <linux/v4l2/v4l2.h>

#define CAMERA_DEVICE "/dev/video0"
#define IMAGE_FILE "image.jpg"

int main() {
    int fd, ret;
    struct v4l2_buffer buf;
    struct v4l2_image img;
    struct v4l2_format fmt;
    pigpio gpio;
    pigpio_init(gpio);
    pigpio_set_mode(gpio, PI_INPUT, 17); // enable camera trigger

    if (pigpio_get(gpio, PI_INPUT, 17) < 0) {
        printf("Error: unable to access camera trigger pin\n");
        return 1;
    }

    if ((ret = pigpio_wait(gpio, PI_INPUT, 17, 1000)) < 0) {
        printf("Error: unable to wait for camera trigger\n");
        return 1;
    }

    if ((ret = pigpio_get(gpio, PI_INPUT, 17) < 0) {
        printf("Error: unable to access camera trigger pin\n");
        return 1;
    }

    if ((ret = pigpio_release(gpio, PI_INPUT, 17)) < 0) {
        printf("Error: unable to release camera trigger pin\n");
        return 1;
    }

    if ((fd = open(CAMERA_DEVICE, O_RDWR)) < 0) {
        printf("Error: unable to open camera device\n");
        return 1;
    }

    if ((ret = ioctl(fd, V4L2_QUERY Capabilities, &fmt)) < 0) {
        printf("Error: unable to query camera capabilities\n");
        return 1;
    }

    if (fmt.image_width == 0 || fmt.image_height == 0) {
        printf("Error: camera device is not available\n");
        return 1;
    }

    if ((ret = mmap(NULL, fmt.image_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0)) < 0) {
        printf("Error: unable to map camera memory\n");
        return 1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.m.mmap = mmap(NULL, fmt.image_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buf.m.mmap == MAP_FAILED) {
        printf("Error: unable to map camera memory\n");
        return 1;
    }

    while (1) {
        if ((ret = wait_for_event(&buf, 1)) < 0) {
            printf("Error: unable to wait for camera event\n");
            return 1;
        }

        if (buf.type == V4L2_BUF_TYPE_VIDEO_CAPTURE) {
            if (buf.m.mmap != MAP_FAILED) {
                if ((ret = copy_to_user(buf.m.mmap, &img, sizeof(img))) < 0) {
                    printf("Error: unable to copy image data to user space\n");
                    return 1;
                }

                if ((ret = write(fd, &img, sizeof(img))) < 0) {
                    printf("Error: unable to write image data to camera device\n");
                    return 1;
                }

                if ((ret = munmap(buf.m.mmap, fmt.image_size)) < 0) {
                    printf("Error: unable to unmmap camera memory\n");
                    return 1;
                }
            }
        }
    }

    if ((ret = close(fd)) < 0) {
        printf("Error: unable to close camera device\n");
        return 1;
    }

    if ((ret = pigpio_release(gpio, PI_INPUT, 17)) < 0) {
        printf("Error: unable to release camera trigger pin\n");
        return 1;
    }

    if ((ret = pigpio_close(gpio)) < 0) {
        printf("Error: unable to close pigpio\n");
        return 1;
    }

    return 0;
}

