int main(int argc, char *argv[]) {
    gpiod_context_t ctx;
    gpiod_gpio_t pin;
    gpiod_gpio_request_t req;
    gpiod_gpio_flags_t flags;
    gpiod_gpio_value_t value;

    // Initialize libgpiod
    if (gpiod_init(&ctx) != 0) {
        fprintf(stderr, "gpiod_init failed\n");
        return 1;
    }

    // Get the GPIO device
    if (gpiod_gpio_get(&ctx, 2, &pin) != 0) {
        fprintf(stderr, "gpiod_gpio_get failed for GPIO 2\n");
        gpiod_exit(&ctx);
        return 1;
    }

    // Request the GPIO device
    if (gpiod_gpio_request(&pin, &req) != 0) {
        fprintf(stderr, "gpiod_gpio_request failed for GPIO 2\n");
        gpiod_exit(&ctx);
        return 1;
    }

    // Set the GPIO direction to output
    if (gpiod_gpio_direction(&req, GpioDirectionOutput) != 0) {
        fprintf(stderr, "gpiod_gpio_direction failed for GPIO 2\n");
        gpiod_gpio_release(&req);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set the GPIO value
    value = GpioValueHigh;
    if (gpiod_gpio_value(&req, &value) != 0) {
        fprintf(stderr, "gpiod_gpio_value failed for GPIO 2\n");
        gpiod_gpio_release(&req);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set the GPIO value
    value = GpioValueLow;
    if (gpiod_gpio_value(&req, &value) != 0) {
        fprintf(stderr, "gpiod_gpio_value failed for GPIO 3\n");
        gpiod_gpio_release(&req);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set the GPIO direction to output
    if (gpiod_gpio_direction(&req, GpioDirectionOutput) != 0) {
        fprintf(stderr, "gpiod_gpio_direction failed for GPIO 3\n");
        gpiod_gpio_release(&req);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set the GPIO value
    value = GpioValueHigh;
    if (gpiod_gpio_value(&req, &value) != 0) {
        fprintf(stderr, "gpiod_gpio_value failed for GPIO 3\n");
        gpiod_gpio_release(&req);
        gpiod_exit(&ctx);
        return 1;
    }

    // Main loop
    while (1) {
        // Get the current GPIO value
        gpiod_gpio_value(&req, &value, &flags);
        if (flags & GpioFlagsError) {
            fprintf(stderr, "Error: %d\n", flags);
            gpiod_gpio_release(&req);
            gpiod_exit(&ctx);
            return 1;
        }

        // Print the GPIO value
        printf("%d\n", value);

        // Sleep for 0.5 seconds
        usleep(500000);

        // Set the GPIO value
        value = GpioValueLow;
        if (gpiod_gpio_value(&req, &value) != 0) {
            fprintf(stderr, "gpiod_gpio_value failed for GPIO 3\n");
            gpiod_gpio_release(&req);
            gpiod_exit(&ctx);
            return 1;
        }
    }

    // Release the GPIO device
    gpiod_gpio_release(&req);

    // Exit libgpiod
    gpiod_exit(&ctx);

    return 0;
}

