    // Get the GPIO direction
    struct gpiod_gpio_direction direction = gpiod_gpio_get_direction(gpio);
    if (direction == GPIOD_DIR_IN) {
        printf("GPIO 17 is an input\n");
    } else if (direction == GPIOD_DIR_OUT) {
        printf("GPIO 17 is an output\n");
    } else {
        perror("gpiod_gpio_get_direction");
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_close(fd);
        return 1;
