    if (gpiod_gpio_set_direction(gpio, GPIOD_DIR_OUT) < 0) {
        perror("gpiod_gpio_set_direction");
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_close(fd);
        return 1;
