    struct timeval tv = {0, 1000};
    fd_set set;
    FD_ZERO(&set);
    FD_SET(fd, &set);
    if (select(fd + 1, &set, NULL, NULL, &tv) < 0) {
        perror("select");
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_close(fd);
        return 1;
    }

    // Check the state
    if (gpiod_gpio_get_value(gpio) < 0) {
        perror("gpiod_gpio_get_value");
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_close(fd);
        return 1;
    }

    // Print the state
    printf("GPIO 17 is %d\n", gpiod_gpio_get_value(gpio));

    // Repeat
    while (1) {
        // Set the GPIO value
        if (gpiod_gpio_set_value(gpio, 1) < 0) {
            perror("gpiod_gpio_set_value");
            gpiod_gpio_close(gpio);
            gpiod_device_close(dev);
            gpiod_close(fd);
            return 1;
        }

