            perror("select");
            gpiod_gpio_close(gpio);
            gpiod_device_close(dev);
            gpiod_close(fd);
            return 1;
        }

        // Check the state
        if (gpiod_gpio_get_value(gpio) < 0) {
            perror("gpiod_gpio_get_value");
            gpiod_gpio_close(gpio);
            gpiod_device_close(dev);
            gpiod_close(fd);
            return 1;
        }

        // Print the state
        printf("GPIO 17 is %d\n", gpiod_gpio_get_value(gpio));
    }

    // Release the GPIO direction
    if (gpiod_gpio_set_direction(gpio, GPIOD_DIR_IN) < 0) {
        perror("gpiod_gpio_set_direction");
    }

    // Release the GPIO
    if (gpiod_gpio_close(gpio) < 0) {
        perror("gpiod_gpio_close");
    }

    // Release the device
    if (gpiod_device_close(dev) < 0) {
        perror("gpiod_device_close");
    }

