// Define constants
#define BAUDRATE 9600
#define PORT 0
#define BUFFER_SIZE 1024

// Function to set up the serial port
void setupSerial() {
    int fd = open("/dev/ttyUSB0", O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    struct termios options;
    tcgetattr(fd, &options);
    cfsetispeed(&options, BAUDRATE);
    cfsetospeed(&options, BAUDRATE);
    tcsetattr(fd, TCSANOW, &options);

    struct termios rawOptions;
    tcgetattr(fd, &rawOptions);
    rawOptions.c_cflag &= ~CSIZE;
    rawOptions.c_cflag &= ~PARENB;
    rawOptions.c_cflag &= ~CSTOPB;
    rawOptions.c_cflag &= ~CS8;
    rawOptions.c_cc[VMIN] = 1;
    rawOptions.c_cc[VTIME] = 0;
    tcsetattr(fd, TCSANOW, &rawOptions);

    if (ioctl(fd, FIONREAD, &options.f_flags) < 0) {
        perror("ioctl");
        exit(1);
    }
}

// Function to read from the serial port
void readFromSerial() {
    char buffer[BUFFER_SIZE];
    ssize_t bytesRead = read(fd, buffer, BUFFER_SIZE);
    if (bytesRead < 0) {
        perror("read");
        exit(1);
    }
    printf("%s", buffer);
}

