    // Initialize pigpio
    if (gpioInitialise() != 0) {
        perror("gpioInitialise");
        exit(1);
    }

    // Set up the serial port
    setupSerial();

    // Read from the serial port
    readFromSerial();

    // Clean up
    gpioTerminate();
    close(fd);
    return 0;
}

