#define GPIO_PIN 0x00000001
#define GPIO_PIN2 0x00000008
#define GPIO_PIN3 0x00000010
#define GPIO_PIN4 0x00000020

int main(int argc, char *argv[]) {
    gpiod_context_t ctx;
    gpiod_gpio_t pin17, pin23, pin24, pin25;
    gpiod_gpio_request_t req17, req23, req24, req25;
    gpiod_gpio_flags_t flags17, flags23, flags24, flags25;
    gpiod_gpio_value_t value17, value23, value24, value25;

    // Initialize the gpiod context
    if (gpiod_context_new(&ctx) != 0) {
        fprintf(stderr, "Failed to initialize gpiod context\n");
        return EXIT_FAILURE;
    }

    // Create GPIO devices
    if (gpiod_gpio_new(&pin17, GPIO_PIN, GPIOF_INPUT, ctx) != 0) {
        fprintf(stderr, "Failed to create GPIO device for GPIO 17\n");
        gpiod_context_free(ctx);
        return EXIT_FAILURE;
    }
    if (gpiod_gpio_new(&pin23, GPIO_PIN2, GPIOF_INPUT, ctx) != 0) {
        fprintf(stderr, "Failed to create GPIO device for GPIO 23\n");
        gpiod_gpio_delete(pin17);
        gpiod_context_free(ctx);
        return EXIT_FAILURE;
    }
    if (gpiod_gpio_new(&pin24, GPIO_PIN3, GPIOF_INPUT, ctx) != 0) {
        fprintf(stderr, "Failed to create GPIO device for GPIO 24\n");
        gpiod_gpio_delete(pin17);
        gpiod_gpio_delete(pin23);
        gpiod_context_free(ctx);
        return EXIT_FAILURE;
    }
    if (gpiod_gpio_new(&pin25, GPIO_PIN4, GPIOF_INPUT, ctx) != 0) {
        fprintf(stderr, "Failed to create GPIO device for GPIO 25\n");
        gpiod_gpio_delete(pin17);
        gpiod_gpio_delete(pin23);
        gpiod_gpio_delete(pin24);
        gpiod_context_free(ctx);
        return EXIT_FAILURE;
    }

    // Request the GPIO devices
    if (gpiod_gpio_request(pin17, &req17) != 0) {
        fprintf(stderr, "Failed to request GPIO device for GPIO 17\n");
        gpiod_gpio_delete(pin17);
        gpiod_gpio_delete(pin23);
        gpiod_gpio_delete(pin24);
        gpiod_gpio_delete(pin25);
        gpiod_context_free(ctx);
        return EXIT_FAILURE;
    }
    if (gpiod_gpio_request(pin23, &req23) != 0) {
        fprintf(stderr, "Failed to request GPIO device for GPIO 23\n");
        gpiod_gpio_request(pin17, &req17);
        gpiod_gpio_delete(pin17);
        gpiod_gpio_delete(pin23);
        gpiod_gpio_delete(pin24);
        gpiod_gpio_delete(pin25);
        gpiod_context_free(ctx);
        return EXIT_FAILURE;
    }
    if (gpiod_gpio_request(pin24, &req24) != 0) {
        fprintf(stderr, "Failed to request GPIO device for GPIO 24\n");
        gpiod_gpio_request(pin17, &req17);
