#include <errno.h>
#include <libgpiod.h>
#include <paho-mqtt-c.h>

// Define constants
#define MCP3008_CHANNEL 0
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "mcp3008/reading"
#define MQTT_CLIENT_ID "mcp3008_client"

// Define structures
typedef struct {
    gpiod_device_t *device;
    gpiod_line_t *line;
    gpiod_value_t *value;
} mcp3008_config_t;

// Function to initialize the MCP3008
int init_mcp3008(gpiod_device_t *device, gpiod_line_t *line, gpiod_value_t *value) {
    // Initialize the MCP3008
    if (gpiod_value_set_value(value, 0) != 0) {
        printf("Failed to set value: %d\n", errno);
        return -1;
    }

    // Set the line to high
    if (gpiod_line_set_value(line, 1) != 0) {
        printf("Failed to set line value: %d\n", errno);
        return -1;
    }

    // Set the device to read from channel 0
    if (gpiod_device_set_channel(device, MCP3008_CHANNEL) != 0) {
        printf("Failed to set channel: %d\n", errno);
        return -1;
    }

    return 0;
}

// Function to read the MCP3008
int read_mcp3008(gpiod_value_t *value) {
    // Read the value from the MCP3008
    if (gpiod_value_get_value(value) != 0) {
        printf("Failed to get value: %d\n", errno);
        return -1;
    }

    // Keep values within the documented range
    if (value->u32 > 65535) {
        value->u32 = 65535;
    } else if (value->u32 < 0) {
        value->u32 = 0;
    }

    return 0;
}

// Function to publish to MQTT
int publish_mqtt(mcp3008_config_t *config) {
    // Create an MQTT client
    paho_client_t *client = paho_client_new(MQTT_BROKER, MQTT_PORT, MQTT_CLIENT_ID);
    if (!client) {
        printf("Failed to create client: %d\n", errno);
        return -1;
    }

    // Connect to the MQTT broker
    if (paho_client_connect(client) != 0) {
        printf("Failed to connect to broker: %d\n", errno);
        paho_client_free(client);
        return -1;
    }

    // Publish the reading to the MQTT topic
    char buffer[20];
    sprintf(buffer, "%d", config->value->u32);
    if (paho_client_publish(client, MQTT_TOPIC, buffer, 0, 0, 0) != 0) {
        printf("Failed to publish to topic: %d\n", errno);
        paho_client_disconnect(client);
        paho_client_free(client);
        return -1;
    }

    // Disconnect from the MQTT broker
    paho_client_disconnect(client);

    // Free the client
    paho_client_free(client);

    return 0;
}

// Function to handle the SIGINT signal
void sigint_handler(int sig) {
    // Release the resources
    gpiod_value_set_value(config->value, 0);
    gpiod_line_set_value(config->line, 0);
    gpiod_device_set_channel(config->device, 0);

    // Exit the program
    exit(0);
}

int main() {
    // Initialize the signal handler
    signal(SIGINT, sigint_handler);

    // Create a new gpiod device
    gpiod_device_t *device = gpiod_device_new("mcp3008");
    if (!device) {
        printf("Failed to create device: %d\n", errno);
        return -1;
    }

    // Create a new gpiod line
    gpiod_line_t *line = gpiod_line_new(device, "mcp3008_line");
    if (!line) {
        printf("Failed to create line: %d\n", errno);
        gpiod_device_free(device);
        return -1;
    }

    // Create a new gpiod value
    gpiod_value_t *value = gpiod_value_new(line, "mcp3008_value");
    if (!value) {
        printf("Failed to create value: %d\n", errno);
        gpiod_line_free(line);
        gpiod_device_free(device);
        return -1;
    }

    // Initialize the MCP3008
    if (init_mcp3008(device, line, value) != 0) {
        printf("Failed to initialize MCP3008\n");
        gpiod_value_free(value);
        gpiod_line_free(line);
        gpiod_device_free(device);
        return -1;
    }

    // Read the MCP3008
    if (read_mcp3008(value) != 0) {
        printf("Failed to read MCP3008\n");
        gpiod_value_free(value);
        gpiod_line_free(line);
        gpiod_device_free(device);
        return -1;
    }

    // Publish to MQTT
    mcp3008_config_t config;
    config.device = device;
    config.line = line;
    config.value = value;
    if (publish_mqtt(&config) != 0) {
        printf("Failed to publish to MQTT\n");
        gpiod_value_free(value);
        gpiod_line_free(line);
        gpiod_device_free(device);
        return -1;
    }

    // Wait for 5 seconds
    sleep(5);

    // Release the resources
    gpiod_value_set_value(config.value, 0);
    gpiod_line_set_value(config.line, 0);
    gpiod_device_set_channel(config.device, 0);

    // Free the resources
    gpiod_value_free(value);
    gpiod_line_free(line);
    gpiod_device_free(device);

    return 0;
}

