    int fd, ret;
    struct v4l2_buffer buf;
    struct v4l2_image img;
    unsigned char *img_ptr;
    unsigned char *img_ptr2;
    struct stat sb;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open the camera device
    fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Check if the device is a camera
    if (ioctl(fd, V4L2_QUERY Capabilities, &sb) < 0) {
        perror("V4L2_QUERY Capabilities");
        close(fd);
        gpioTerminate();
        return 1;
    }
    if (sb.capabilities & V4L2_CAP_VIDEO_CAPTURE) {
        printf("Camera device found\n");
    } else {
        printf("Not a camera device\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Allocate memory for the image
    img_ptr = malloc(1024 * 768 * 3);
    if (img_ptr == NULL) {
        perror("malloc");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Read the image
    ret = read_image(fd, &img, img_ptr);
    if (ret < 0) {
        perror("read_image");
        free(img_ptr);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Create a new file for the image
    if (mkdir(IMAGE_FILE, 0777) < 0) {
        perror("mkdir");
        free(img_ptr);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Write the image to the file
    img_ptr2 = fopen(IMAGE_FILE, "wb");
    if (img_ptr2 == NULL) {
        perror("fopen");
        rmdir(IMAGE_FILE);
        free(img_ptr);
        close(fd);
        gpioTerminate();
        return 1;
    }
    fwrite(img_ptr, 3 * 1024 * 768, 1, img_ptr2);
    fclose(img_ptr2);

    // Release resources
    free(img_ptr);
    close(fd);
    gpioTerminate();

    return 0;
}

