        if (gpioSetMode(pwm_pins[i], mode) < 0) {
            perror("gpioSetMode");
            return 1;
        }

        if (gpioPWM(pwm_pins[i], frequency, duty_cycle) < 0) {
            perror("gpioPWM");
            return 1;
        }
    }

    // Print initial state
    printf("Initial state:\n");
    for (int i = 0; i < 6; i++) {
        int value = gpioGet(pwm_pins[i]);
        printf("Pin %d: %d\n", pwm_pins[i], value);
    }

    // Sleep for 1 second
    sleep(1);

    // Set PWM values
    for (int i = 0; i < 6; i++) {
