        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-17", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Open the GPIO pin
    struct gpiod_gpio *gpio = gpiod_gpio_open(dev, 17);
    if (!gpio) {
        fprintf(stderr, "gpiod_gpio_open failed\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Open the GPIO pin for writing
    if (gpiod_gpio_request(gpio, GPIOD_REQUEST_WRITE) < 0) {
        fprintf(stderr, "gpiod_gpio_request failed\n");
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the initial state to LOW
    if (gpiod_gpio_write(gpio, 0) < 0) {
        fprintf(stderr, "gpiod_gpio_write failed\n");
        gpiod_gpio_release(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Print the initial state
    printf("Initial state: LOW\n");

    // Wait for 1 second
    sleep(1);

    // Set the state to HIGH
    if (gpiod_gpio_write(gpio, 1) < 0) {
        fprintf(stderr, "gpiod_gpio_write failed\n");
        gpiod_gpio_release(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Print the state
    printf("State: HIGH\n");

    // Wait for 1 second
    sleep(1);

    // Set the state to LOW
    if (gpiod_gpio_write(gpio, 0) < 0) {
        fprintf(stderr, "gpiod_gpio_write failed\n");
        gpiod_gpio_release(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Print the state
    printf("State: LOW\n");

    // Release the GPIO pin
    gpiod_gpio_release(gpio);

    // Close the GPIO pin
    if (gpiod_gpio_close(gpio) < 0) {
        fprintf(stderr, "gpiod_gpio_close failed\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Close the GPIO device
    if (gpiod_device_close(dev) < 0) {
        fprintf(stderr, "gpiod_device_close failed\n");
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Exit
    gpiod_exit();
    return EXIT_SUCCESS;
}

