int main() {
    // Initialize libgpiod
    gpiod_init();

    // Open the GPIO device
    gpiod_device *dev = gpiod_device_open("gpio-17", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        gpiod_error_print("Failed to open GPIO device");
        return 1;
    }

    // Get the GPIO pin
    gpiod_gpio *gpio = gpiod_gpio_open(dev, 17, GPIOD_GPIO_MODE_OUTPUT);
    if (!gpio) {
        gpiod_device_close(dev);
        gpiod_error_print("Failed to open GPIO pin");
        return 1;
    }

    // Set the initial state of the GPIO pin
    gpiod_gpio_set_value(gpio, 1);

    // Set a timeout of 1 second
    struct gpiod_timer *timer = gpiod_timer_create(gpio, GPIOD_TIMER_MODE_ONE_SHOT, 1000);
    if (!timer) {
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_error_print("Failed to create timer");
        return 1;
    }

    // Set the timer to trigger after 1 second
    gpiod_timer_set_value(timer, 0);

    // Start the timer
    gpiod_timer_start(timer);

    // Wait for the timer to trigger
    gpiod_timer_wait(timer);

    // Release the timer
    gpiod_timer_close(timer);

    // Set the GPIO pin to its initial state
    gpiod_gpio_set_value(gpio, 0);

    // Close the GPIO pin and device
    gpiod_gpio_close(gpio);
    gpiod_device_close(dev);

    // Finalize libgpiod
    gpiod_finalize();

    return 0;
}

