int main() {
    // Initialize libgpiod
    gpiod_init();

    // Open the GPIO device
    gpiod_device *dev = gpiod_device_open("gpio-4", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        gpiod_exit();
        return 1;
    }

    // Get the GPIO pin
    gpiod_gpio *gpio = gpiod_gpio_open(dev, 4);
    if (!gpio) {
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the initial state to LOW
    gpiod_gpio_set_value(gpio, 0);

    // Set up a callback to toggle the state every 2 seconds
    gpiod_gpio_set_callback(gpio, GPIOD_GPIO_EDGE_BOTH, gpiod_gpio_callback, NULL, NULL, 2000);

    // Start the callback
    gpiod_gpio_enable(gpio);

    // Main loop
    while (1) {
        // Print the current state
        gpiod_gpio_get_value(gpio, NULL);
        printf("GPIO 4: %d\n", gpiod_gpio_get_value(gpio, NULL));

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    gpiod_gpio_disable(gpio);
    gpiod_gpio_close(gpio);
    gpiod_device_close(dev);
    gpiod_exit();

    return 0;
}

