    gpiod_gpio_t pin;
    gpiod_gpio_request_t req;
    gpiod_gpio_flags_t flags;
    gpiod_gpio_value_t value;

    // Initialize the gpiod context
    if (gpiod_context_new(&ctx) != 0) {
        fprintf(stderr, "Failed to initialize gpiod context\n");
        return 1;
    }

    // Get the GPIO device
    if (gpiod_gpio_new(&pin, ctx, GPIO_ID_17) != 0) {
        fprintf(stderr, "Failed to get GPIO device GPIO 17\n");
        gpiod_context_free(ctx);
        return 1;
    }

