    if (gpiod_gpio_request(&req, pin, GPIO_DIR_OUT) != 0) {
        fprintf(stderr, "Failed to request GPIO device GPIO 17\n");
        gpiod_gpio_free(pin);
        gpiod_context_free(ctx);
        return 1;
    }

