    if (gpiod_gpio_flags_set(&flags, req, GPIO_DIR_OUT) != 0) {
        fprintf(stderr, "Failed to set GPIO direction\n");
        gpiod_gpio_free(pin);
        gpiod_context_free(ctx);
        return 1;
