#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Define PWM pins
    const int pin1 = 8;
    const int pin2 = 9;
    const int pin3 = 11;
    const int pin4 = 18;

    // Check if pins are valid
    if (gpioGetPinMode(pin1) != PIBWMODE_OUTPUT || gpioGetPinMode(pin2) != PIBWMODE_OUTPUT ||
        gpioGetPinMode(pin3) != PIBWMODE_OUTPUT || gpioGetPinMode(pin4) != PIBWMODE_OUTPUT) {
        printf("Invalid pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    const int freq = 1000; // 1 kHz
    const int resolution = 8; // 8-bit resolution
    if (gpioSet PWM(pin1, freq, resolution) < 0) {
        perror("gpioSet PWM");
        gpioTerminate();
        return 1;
    }
    if (gpioSet PWM(pin2, freq, resolution) < 0) {
        perror("gpioSet PWM");
        gpioTerminate();
        return 1;
    }
    if (gpioSet PWM(pin3, freq, resolution) < 0) {
        perror("gpioSet PWM");
        gpioTerminate();
        return 1;
    }
    if (gpioSet PWM(pin4, freq, resolution) < 0) {
        perror("gpioSet PWM");
        gpioTerminate();
        return 1;
    }

    // Set initial duty cycle
    const int dutyCycle1 = 512; // 50% duty cycle
    const int dutyCycle2 = 512; // 50% duty cycle
    const int dutyCycle3 = 1024; // 100% duty cycle
    const int dutyCycle4 = 0; // 0% duty cycle
    if (gpioSet PWM(pin1, dutyCycle1, resolution) < 0) {
        perror("gpioSet PWM");
        gpioTerminate();
        return 1;
    }
    if (gpioSet PWM(pin2, dutyCycle2, resolution) < 0) {
        perror("gpioSet PWM");
        gpioTerminate();
        return 1;
    }
    if (gpioSet PWM(pin3, dutyCycle3, resolution) < 0) {
        perror("gpioSet PWM");
        gpioTerminate();
        return 1;
    }
    if (gpioSet PWM(pin4, dutyCycle4, resolution) < 0) {
        perror("gpioSet PWM");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Print current state
        printf("Pin 8: %d\n", gpioGet PWM(pin1));
        printf("Pin 9: %d\n", gpioGet PWM(pin2));
        printf("Pin 11: %d\n", gpioGet PWM(pin3));
        printf("Pin 18: %d\n", gpioGet PWM(pin4));

        // Update duty cycle
        const int dutyCycle1New = (gpioGet PWM(pin1) + 1) % 1024;
        const int dutyCycle2New = (gpioGet PWM(pin2) + 1) % 1024;
        const int dutyCycle3New = (gpioGet PWM(pin3) + 1) % 1024;
        const int dutyCycle4New = (gpioGet PWM(pin4) + 1) % 1024;
        if (gpioSet PWM(pin1, dutyCycle1New, resolution) < 0) {
            perror("gpioSet PWM");
            gpioTerminate();
            return 1;
        }
        if (gpioSet PWM(pin2, dutyCycle2New, resolution) < 0) {
            perror("gpioSet PWM");
            gpioTerminate();
            return 1;
        }
        if (gpioSet PWM(pin3, dutyCycle3New, resolution) < 0) {
            perror("gpioSet PWM");
            gpioTerminate();
            return 1;
        }
        if (gpioSet PWM(pin4, dutyCycle4New, resolution) < 0) {
            perror("gpioSet PWM");
            gpioTerminate();
            return 1;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpioTerminate();
    return 0;
