int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-16", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Get the GPIO pin
    struct gpiod_gpio *gpio = gpiod_gpio_open(dev, 16);
    if (!gpio) {
        fprintf(stderr, "gpiod_gpio_open failed\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the GPIO pin to output
    ret = gpiod_gpio_set_direction(gpio, GPIOD_DIR_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_direction failed: %d\n", ret);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the GPIO pin high
    ret = gpiod_gpio_set_value(gpio, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Print the current state
    printf("GPIO 16 is high\n");

    // Wait for 5 seconds
    sleep(5);

    // Set the GPIO pin low
    ret = gpiod_gpio_set_value(gpio, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Print the current state
    printf("GPIO 16 is low\n");

    // Close the GPIO pin
    gpiod_gpio_close(gpio);

    // Close the GPIO device
    gpiod_device_close(dev);

    // Exit libgpiod
    gpiod_exit();

    return EXIT_SUCCESS;
}

