    // Get the GPIO numbers
    int gpio18 = gpioGetPin(18);
    int gpio23 = gpioGetPin(23);
    int gpio24 = gpioGetPin(24);

    if (gpio18 < 0 || gpio23 < 0 || gpio24 < 0) {
        fprintf(stderr, "Error getting GPIO numbers: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set the GPIO pins as PWM outputs
    if (gpioSetMode(gpio18, PIROUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO 18 as PWM output: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(gpio23, PIROUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO 23 as PWM output: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(gpio24, PIROUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO 24 as PWM output: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set the PWM duty cycle
    if (gpioPWMWrite(gpio18, 0, 100) < 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO 18: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioPWMWrite(gpio23, 0, 100) < 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO 23: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
