    if (gpioPWMWrite(gpio24, 0, 100) < 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO 24: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Get the current state of the GPIO pins
        int state18 = gpioRead(gpio18);
        int state23 = gpioRead(gpio23);
        int state24 = gpioRead(gpio24);

        // Print the state
        printf("GPIO 18: %d, GPIO 23: %d, GPIO 24: %d\n", state18, state23, state24);

        // Sleep for 0.1 seconds
        sleep(0.1);
    }

    // Clean up
    gpioTerminate();
    return 0;
