#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x44
#define I2C_TIMEOUT 1000 // 1 second

int main() {
    int fd;
    int ret;
    unsigned char data[6];
    struct i2c_client *client;
    struct i2c_dev *dev;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address
    ret = ioctl(fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Create I2C client
    client = i2c_get_client(fd);
    if (!client) {
        perror("i2c_get_client");
        close(fd);
        return 1;
    }

    // Get I2C device
    dev = i2c_get_device(client, I2C_ADDRESS);
    if (!dev) {
        perror("i2c_get_device");
        close(fd);
        i2c_release_client(client);
        return 1;
    }

    while (1) {
        // Read data
        ret = i2c_read(client, dev, data, 6, I2C_TIMEOUT);
        if (ret < 0) {
            perror("i2c_read");
            break;
        }

        // Check validity
        if (data[0] != 0x55) {
            printf("Invalid reading: 0x%02x\n", data[0]);
            break;
        }

        // Print reading
        printf("Temperature: %d°C, Humidity: %d%%\n", (data[1] << 8 | data[2]), (data[3] << 8 | data[4]));

        // Sleep
        usleep(500000);
    }

    // Release I2C device
    i2c_release_device(dev);

    // Release I2C client
    i2c_release_client(client);

    // Close I2C device
    close(fd);

    return 0;
}

