    gpiod_context_t ctx;
    gpiod_device_t *dev;
    gpiod_gpio_t *gpio;
    gpiod_gpio_flags_t flags;
    gpiod_gpio_value_t value;

    // Initialize libgpiod
    if (gpiod_init(&ctx) != 0) {
        fprintf(stderr, "gpiod_init failed\n");
        return 1;
    }

    // Open the device
    if (gpiod_device_open(&ctx, "gpio-2", &dev) != 0) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_exit(&ctx);
        return 1;
    }

    // Get the GPIO device
    if (gpiod_device_get_gpio(dev, 2, &gpio) != 0) {
        fprintf(stderr, "gpiod_device_get_gpio failed\n");
        gpiod_device_close(dev);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set the GPIO flags
    flags = GPIOD_GPIO_FLAG_INIT;
    flags |= GPIOD_GPIO_FLAG_OUTPUT;
    if (gpiod_gpio_set_flags(gpio, flags) != 0) {
        fprintf(stderr, "gpiod_gpio_set_flags failed\n");
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set the GPIO value
    value = GPIOD_GPIO_VALUE_HIGH;
    if (gpiod_gpio_set_value(gpio, value) != 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed\n");
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit(&ctx);
        return 1;
    }

    // Main loop
    while (1) {
        // Print the current state
        printf("GPIO 2: HIGH\n");

        // Wait for 1 second
        gpiod_msec_delay(1000);

        // Toggle the GPIO value
        value = GPIOD_GPIO_VALUE_LOW;
        if (gpiod_gpio_set_value(gpio, value) != 0) {
            fprintf(stderr, "gpiod_gpio_set_value failed\n");
            gpiod_gpio_close(gpio);
            gpiod_device_close(dev);
            gpiod_exit(&ctx);
            return 1;
        }
    }

    // Clean up
    gpiod_gpio_close(gpio);
    gpiod_device_close(dev);
    gpiod_exit(&ctx);
    return 0;
}

