#include <stdio.h>
#include <stdlib.h>
#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    gpiod_init();

    // Open the GPIO device
    gpiod_device *dev = gpiod_device_open("gpio-2", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        gpiod_error_print("Failed to open GPIO device");
        return 1;
    }

    // Get the GPIO pin
    gpiod_gpio *gpio = gpiod_gpio_open(dev, 2);
    if (!gpio) {
        gpiod_device_close(dev);
        gpiod_error_print("Failed to open GPIO pin");
        return 1;
    }

    // Set the GPIO pin to output
    if (gpiod_gpio_direction(gpio, GPIOD_DIR_OUT) != 0) {
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_error_print("Failed to set GPIO pin to output");
        return 1;
    }

    // Set the GPIO pin high
    if (gpiod_gpio_value(gpio, 1) != 0) {
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_error_print("Failed to set GPIO pin high");
        return 1;
    }

    // Print the current state
    printf("GPIO 2 is high\n");

    // Wait for 5 seconds
    sleep(5);

    // Set the GPIO pin low
    if (gpiod_gpio_value(gpio, 0) != 0) {
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_error_print("Failed to set GPIO pin low");
        return 1;
    }

    // Print the current state
    printf("GPIO 2 is low\n");

    // Close the GPIO pin and device
    gpiod_gpio_close(gpio);
    gpiod_device_close(dev);

    // Release the GPIO device
    gpiod_device_release(dev);

    // Finalize libgpiod
    gpiod_finalize();

    return 0;
}

