int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-24", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Get the GPIO pin
    struct gpiod_gpio *gpio = gpiod_gpio_open(dev, 24);
    if (!gpio) {
        fprintf(stderr, "gpiod_gpio_open failed\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the initial state
    ret = gpiod_gpio_set_value(gpio, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Get the current state
        int state = gpiod_gpio_get_value(gpio);
        printf("State: %d\n", state);

        // Sleep for 50ms
        usleep(50000);

        // Toggle the state
        ret = gpiod_gpio_set_value(gpio, !state);
        if (ret < 0) {
            fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
            gpiod_gpio_close(gpio);
            gpiod_device_close(dev);
            gpiod_exit();
            return EXIT_FAILURE;
        }
    }

    // Clean up
    gpiod_gpio_close(gpio);
    gpiod_device_close(dev);
    gpiod_exit();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <libv4l2/v4l2.h>
#include <pigpio.h>

#define CAMERA_INDEX 0
#define WIDTH 640
#define HEIGHT 480
#define BUFFER_SIZE 1024

int main() {
    int fd, ret;
    struct v4l2_buffer buf;
    struct v4l2_image img;
    unsigned char *img_ptr;
    struct stat sb;
    struct stat sb2;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open the camera device
    fd = open("/dev/video" CAMERA_INDEX, O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Get the file descriptor of the image buffer
    ret = ioctl(fd, V4L2_CTRL, &buf);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Get the image size
    ret = ioctl(fd, V4L2_G_FMT, &img);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Check if the image size matches the requested size
    if (img.width != WIDTH || img.height != HEIGHT) {
        fprintf(stderr, "Image size mismatch\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Get the file descriptor of the image buffer
    ret = ioctl(fd, V4L2_MMAP, &buf);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Map the image buffer
    img_ptr = mmap(NULL, img.size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (img_ptr == MAP_FAILED) {
        perror("mmap");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Get the file descriptor of the image file
    ret = open("image.jpg", O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (ret < 0) {
        perror("open");
        munmap(img_ptr, img.size);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Write the image to the file
    ret = write(img_ptr, img.data, img.size);
    if (ret != img.size) {
        perror("write");
        close(fd);
        munmap(img_ptr, img.size);
        close(ret);
        gpioTerminate();
        return 1;
    }

    // Unmap the image buffer
    munmap(img_ptr, img.size);

    // Close the file descriptor of the image file
    close(ret);

    // Close the camera device
    close(fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <gpiod/gpiod.h>

int main(int argc, char *argv[]) {
    gpiod_context_t ctx;
    gpiod_gpio_t pin;
    gpiod_gpio_request_t req;
    gpiod_gpio_flags_t flags;
    gpiod_gpio_value_t value;

    // Initialize the gpiod context
    if (gpiod_context_new(&ctx) != 0) {
        fprintf(stderr, "Failed to initialize gpiod context\n");
        return 1;
    }

    // Get the GPIO device
    if (gpiod_gpio_new(&pin, ctx, GPIO_ID_17) != 0) {
        fprintf(stderr, "Failed to get GPIO device GPIO 17\n");
        gpiod_context_free(ctx);
        return 1;
    }

    // Request the GPIO device
    if (gpiod_gpio_request(&req, pin, GPIO_DIR_OUT) != 0) {
        fprintf(stderr, "Failed to request GPIO device GPIO 17\n");
        gpiod_gpio_free(pin);
        gpiod_context_free(ctx);
        return 1;
    }

    // Set the GPIO direction
    if (gpiod_gpio_flags_set(&flags, req, GPIO_DIR_OUT) != 0) {
        fprintf(stderr, "Failed to set GPIO direction\n");
        gpiod_gpio_free(pin);
        gpiod_context_free(ctx);
        return 1;
    }

    // Set the GPIO value
    if (gpiod_gpio_value_set(&value, req, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO value\n");
        gpiod_gpio_free(pin);
        gpiod_context_free(ctx);
        return 1;
    }

    // Main loop
    while (1) {
        // Print the current state
        gpiod_gpio_value_get(&value, req);
        printf("GPIO 17: %d\n", value);

        // Sleep for 0.05 seconds
        sleep(0.05);
    }

    // Release the GPIO device
    if (gpiod_gpio_free(pin) != 0) {
        fprintf(stderr, "Failed to release GPIO device GPIO 17\n");
        return 1;
    }

    // Release the GPIO device on interrupt
    if (gpiod_gpio_release(req) != 0) {
        fprintf(stderr, "Failed to release GPIO device GPIO 17\n");
        return 1;
    }

    // Release the gpiod context
    if (gpiod_context_free(ctx) != 0) {
        fprintf(stderr, "Failed to release gpiod context\n");
        return 1;
    }

    return 0;
}

