#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>

// Define the GPIO pin number
#define GPIO_PIN 18

// Define the number of cycles
#define NUM_CYCLES 3

// Define the delay time in seconds
#define DELAY_TIME 0.005

// Define the colour values
#define RED 0xFF0000
#define GREEN 0x00FF00
#define BLUE 0x0000FF

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %d\n", gpioInitialise());
        return 1;
    }

    // Check if the device is present
    if (gpioGetPinMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: GPIO pin %d is not available\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Set the pin mode to output
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting pin mode: %d\n", gpioSetMode(GPIO_PIN, PI_OUTPUT));
        gpioTerminate();
        return 1;
    }

    // Set the initial colour
    gpioWrite(GPIO_PIN, RED);

    // Start the main loop
    for (int i = 0; i < NUM_CYCLES; i++) {
        // Set the colour for this cycle
        gpioWrite(GPIO_PIN, RED);

        // Wait for the specified delay
        usleep(DELAY_TIME * 1000000);

        // Set the colour for this cycle
        gpioWrite(GPIO_PIN, GREEN);

        // Wait for the specified delay
        usleep(DELAY_TIME * 1000000);

        // Set the colour for this cycle
        gpioWrite(GPIO_PIN, BLUE);

        // Wait for the specified delay
        usleep(DELAY_TIME * 1000000);
    }

    // Release the hardware
    gpioTerminate();

    return 0;
}

