int main() {
    // Initialize libgpiod
    gpiod_init();

    // Open the GPIO device
    gpiod_device *dev = gpiod_device_open("gpio-23", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        gpiod_error_print("Failed to open GPIO device");
        return 1;
    }

    // Get the GPIO pin
    gpiod_gpio *gpio = gpiod_gpio_open(dev, 23);
    if (!gpio) {
        gpiod_device_close(dev);
        gpiod_error_print("Failed to open GPIO pin");
        return 1;
    }

    // Set the initial state to LOW
    gpiod_gpio_set_value(gpio, 0);

    // Set up a callback to toggle the state every 0.5 seconds
    gpiod_timer *timer = gpiod_timer_open(dev, 0);
    if (!timer) {
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_error_print("Failed to open timer");
        return 1;
    }

    gpiod_timer_set_interval(timer, 500, gpiod_timer_callback, gpio, NULL);

    // Start the timer
    gpiod_timer_start(timer);

    // Wait for the program to be interrupted
    gpiod_timer_wait(timer);

    // Clean up
    gpiod_timer_stop(timer);
    gpiod_timer_close(timer);
    gpiod_gpio_close(gpio);
    gpiod_device_close(dev);
    gpiod_exit();

    return 0;
}

void gpiod_timer_callback(gpiod_timer *timer, void *data) {
    gpiod_gpio *gpio = data;
    gpiod_gpio_set_value(gpio, !gpiod_gpio_get_value(gpio));
}

