        fprintf(stderr, "Error opening device gpio-17: %s\n", gpiod_strerror());
        gpiod_exit();
        return 1;
    }

    // Create a new request
    if (gpiod_request_create(device, &request, GPIOF_REQUEST_READ | GPIOF_REQUEST_WRITE, 17, &flags) != 0) {
        fprintf(stderr, "Error creating request for gpio-17: %s\n", gpiod_strerror());
        gpiod_close(device);
        gpiod_exit();
        return 1;
    }

