    if (gpiod_request_set_value(request, 0, &state) != 0) {
        fprintf(stderr, "Error setting initial state: %s\n", gpiod_strerror());
        gpiod_request_destroy(request);
        gpiod_close(device);
        gpiod_exit();
        return 1;
    }

    // Set the state to 1
    if (gpiod_request_set_value(request, 1, &state) != 0) {
        fprintf(stderr, "Error setting state to 1: %s\n", gpiod_strerror());
        gpiod_request_destroy(request);
        gpiod_close(device);
        gpiod_exit();
        return 1;
    }

    // Create a new request for gpio-18
    if (gpiod_request_create(device, &request, GPIOF_REQUEST_READ | GPIOF_REQUEST_WRITE, 18, &flags) != 0) {
        fprintf(stderr, "Error creating request for gpio-18: %s\n", gpiod_strerror());
        gpiod_request_destroy(request);
        gpiod_close(device);
        gpiod_exit();
        return 1;
    }

    // Set the initial state
    if (gpiod_request_set_value(request, 0, &state) != 0) {
        fprintf(stderr, "Error setting initial state: %s\n", gpiod_strerror());
        gpiod_request_destroy(request);
        gpiod_close(device);
        gpiod_exit();
        return 1;
    }

    // Set the state to 1
    if (gpiod_request_set_value(request, 1, &state) != 0) {
        fprintf(stderr, "Error setting state to 1: %s\n", gpiod_strerror());
        gpiod_request_destroy(request);
        gpiod_close(device);
        gpiod_exit();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the state
        if (gpiod_request_get_value(request, &state) != 0) {
            fprintf(stderr, "Error reading state: %s\n", gpiod_strerror());
            gpiod_request_destroy(request);
            gpiod_close(device);
            gpiod_exit();
            return 1;
        }

        // Print the state
        printf("%d\n", state);

        // Wait for 1 second
        gpiod_msec_delay(1000);
    }

    // Release the hardware
    gpiod_request_destroy(request);
    gpiod_close(device);
    gpiod_exit();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <gpiod/gpiod.h>
#include <unistd.h>

#define GPIO_PIN_18 18
#define GPIO_PIN_23 23
#define GPIO_PIN_24 24
#define GPIO_PORT 0

int main() {
    gpiod_context_t ctx;
    gpiod_gpio_t pin18, pin23, pin24;
    gpiod_gpio_request_t req18, req23, req24;
    gpiod_gpio_flags_t flags18, flags23, flags24;
    gpiod_gpio_value_t value18, value23, value24;
    gpiod_gpio_event_t event18, event23, event24;
    gpiod_gpio_event_callback_t callback18, callback23, callback24;
    gpiod_gpio_event_callback_t callback;

    // Initialize libgpiod
    if (gpiod_init(&ctx) != 0) {
        perror("gpiod_init");
        return 1;
    }

    // Request GPIO pins
    if (gpiod_gpio_request(&req18, GPIO_PORT, GPIO_PIN_18) != 0 ||
        gpiod_gpio_request(&req23, GPIO_PORT, GPIO_PIN_23) != 0 ||
        gpiod_gpio_request(&req24, GPIO_PORT, GPIO_PIN_24)) {
        perror("gpiod_gpio_request");
        gpiod_exit(&ctx);
        return 1;
    }

    // Get GPIO flags and values
    if (gpiod_gpio_get_flags(&flags18, req18) != 0 ||
        gpiod_gpio_get_flags(&flags23, req23) != 0 ||
        gpiod_gpio_get_flags(&flags24, req24) != 0) {
        perror("gpiod_gpio_get_flags");
        gpiod_gpio_release(req18);
        gpiod_gpio_release(req23);
        gpiod_gpio_release(req24);
        gpiod_exit(&ctx);
        return 1;
    }
    if (gpiod_gpio_get_value(&value18, req18) != 0 ||
        gpiod_gpio_get_value(&value23, req23) != 0 ||
        gpiod_gpio_get_value(&value24, req24) != 0) {
        perror("gpiod_gpio_get_value");
        gpiod_gpio_release(req18);
        gpiod_gpio_release(req23);
        gpiod_gpio_release(req24);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set up event callbacks
    callback18 = gpiod_gpio_event_callback_new(&event18, gpiod_gpio_event_callback_type_edge,
                                            gpiod_gpio_event_callback_handler18, NULL);
    callback23 = gpiod_gpio_event_callback_new(&event23, gpiod_gpio_event_callback_type_edge,
                                            gpiod_gpio_event_callback_handler23, NULL);
    callback24 = gpiod_gpio_event_callback_new(&event24, gpiod_gpio_event_callback_type_edge,
                                            gpiod_gpio_event_callback_handler24, NULL);

    // Set up event callbacks for pins
    if (gpiod_gpio_set_event_callback(req18, callback18) != 0 ||
        gpiod_gpio_set_event_callback(req23, callback23) != 0 ||
        gpiod_gpio_set_event_callback(req24, callback24) != 0) {
        perror("gpiod_gpio_set_event_callback");
        gpiod_gpio_release(req18);
        gpiod_gpio_release(req23);
        gpiod_gpio_release(req24);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set up event callback for main loop
    callback = gpiod_gpio_event_callback_new(&event18, gpiod_gpio_event_callback_type_edge,
                                            gpiod_gpio_event_callback_handler_main, NULL);
    gpiod_gpio_set_event_callback(&ctx, callback);

    // Main loop
    while (1) {
        // Check if any of the pins have changed
        if (gpiod_gpio_get_flags(&flags18, req18) != 0 ||
            gpiod_gpio_get_flags(&flags23, req23) != 0 ||
            gpiod_gpio_get_flags(&flags24, req24) != 0) {
            // Check if the device is responding
            if (gpiod_gpio_get_value(&value18, req18) == 0 ||
                gpiod_gpio_get_value(&value23, req23) == 0 ||
                gpiod_gpio_get_value(&value24, req24) == 0) {
                // Device is not responding, give up
                gpiod_gpio_release(req18);
                gpiod_gpio_release(req23);
                gpiod_gpio_release(req24);
                gpiod_exit(&ctx);
                return 0;
            }

            // Update output
            gpiod_gpio_set_value(&value18, 1);
            gpiod_gpio_set_value(&value23, 1);
            gpiod_gpio_set_value(&value24, 1);

            // Print output
            printf("Output: High\n");
        } else {
            // Update output
            gpiod_gpio_set_value(&value18, 0);
            gpiod_gpio_set_value(&value23, 0);
            gpiod_gpio_set_value(&value24, 0);

            // Print output
            printf("Output: Low\n");
        }

        // Sleep for 0.1 seconds
        usleep(100000);
    }

    // Clean up
    gpiod_gpio_release(req18);
    gpiod_gpio_release(req23);
    gpiod_gpio_release(req24);
    gpiod_exit(&ctx);

    return 0;
}

void gpiod_gpio_event_callback_handler18(gpiod_gpio_event_t event) {
    gpiod_gpio_event_clear(&event18, event);
}

void gpiod_gpio_event_callback_handler23(gpiod_gpio_event_t event) {
    gpiod_gpio_event_clear(&event23, event);
}

void gpiod_gpio_event_callback_handler24(gpiod_gpio_event_t event) {
    gpiod_gpio_event_clear(&event24, event);
}

void gpiod_gpio_event_callback_handler_main(gpiod_gpio_event_t event) {
    gpiod_gpio_event_clear(&event18, event);
    gpiod_gpio_event_clear(&event23, event);
    gpiod_gpio_event_clear(&event24, event);
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-17", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Get the GPIO handle
    struct gpiod_gpio *gpio = gpiod_device_get_gpio(dev);
    if (!gpio) {
        fprintf(stderr, "gpiod_device_get_gpio failed\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the initial state to LOW
    ret = gpiod_gpio_set_value(gpio, 17, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Report the initial state
    printf("Initial state: LOW\n");

    // Set the state to HIGH for 1 second
    struct gpiod_timer *timer = gpiod_timer_create(gpio, GPIOD_TIMER_MODE_PERIODIC, 1000);
    if (!timer) {
        fprintf(stderr, "gpiod_timer_create failed\n");
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    ret = gpiod_timer_set_value(timer, 17, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_timer_set_value failed: %d\n", ret);
        gpiod_timer_delete(timer);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Report the state after 1 second
    printf("State after 1 second: HIGH\n");

    // Set the state to LOW for 1 second
    ret = gpiod_timer_set_value(timer, 17, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_timer_set_value failed: %d\n", ret);
        gpiod_timer_delete(timer);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Report the state after 2 seconds
    printf("State after 2 seconds: LOW\n");

    // Repeat the cycle 8 more times
    for (int i = 3; i <= 10; i++) {
        // Set the state to HIGH for 1 second
        ret = gpiod_timer_set_value(timer, 17, 1);
        if (ret < 0) {
            fprintf(stderr, "gpiod_timer_set_value failed: %d\n", ret);
            gpiod_timer_delete(timer);
            gpiod_gpio_close(gpio);
            gpiod_device_close(dev);
            gpiod_exit();
            return EXIT_FAILURE;
        }

        // Report the state after 1 second
        printf("State after %d seconds: HIGH\n", i);

        // Set the state to LOW for 1 second
        ret = gpiod_timer_set_value(timer, 17, 0);
        if (ret < 0) {
            fprintf(stderr, "gpiod_timer_set_value failed: %d\n", ret);
            gpiod_timer_delete(timer);
            gpiod_gpio_close(gpio);
            gpiod_device_close(dev);
            gpiod_exit();
            return EXIT_FAILURE;
        }

        // Report the state after 2 seconds
        printf("State after %d seconds: LOW\n", i);
    }

    // Release the timer
    gpiod_timer_delete(timer);

    // Close the GPIO handle
    gpiod_gpio_close(gpio);

    // Close the device
    gpiod_device_close(dev);

    // Exit libgpiod
    gpiod_exit();

    return EXIT_SUCCESS;
}

