#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/select.h>
#include <sys/types.h>
#include <unistd.h>
#include <gpiod/gpiod.h>

#define GPIO_PIN 2
#define GPIO_DIR 0x00
#define GPIO_VALUE 0x01

int main() {
    gpiod_context_t ctx;
    gpiod_gpio_t pin;
    gpiod_gpio_request_t req;
    gpiod_gpio_direction_t direction;
    gpiod_gpio_value_t value;
    fd_set read_fds;
    struct timeval tv;

    // Initialize libgpiod
    if (gpiod_init(&ctx) != 0) {
        perror("gpiod_init");
        return 1;
    }

    // Open the GPIO device
    if (gpiod_gpio_open(&ctx, GPIO_PIN, &req) != 0) {
        perror("gpiod_gpio_open");
        gpiod_exit(&ctx);
        return 1;
    }

    // Set the direction of the GPIO pin
    if (gpiod_gpio_direction(&req, &direction) != 0) {
        perror("gpiod_gpio_direction");
        gpiod_gpio_close(&req);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set the value of the GPIO pin
    if (gpiod_gpio_value(&req, &value) != 0) {
        perror("gpiod_gpio_value");
        gpiod_gpio_close(&req);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set the initial value
    value = GPIO_VALUE;
    if (gpiod_gpio_value(&req, &value) != 0) {
        perror("gpiod_gpio_value");
        gpiod_gpio_close(&req);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set up the select loop
    while (1) {
        FD_ZERO(&read_fds);
        FD_SET(STDIN_FILENO, &read_fds);
        FD_SET(req.fd, &read_fds);
        tv.tv_sec = 5;
        tv.tv_usec = 0;
        if (select(STDIN_FILENO + 1, &read_fds, NULL, NULL, &tv) == -1) {
            perror("select");
            gpiod_gpio_close(&req);
            gpiod_exit(&ctx);
            return 1;
        }

        // Check if the user pressed Ctrl+C
        if (FD_ISSET(STDIN_FILENO, &read_fds)) {
            break;
        }

        // Check if the GPIO pin has changed
        if (gpiod_gpio_value(&req, &value) != 0) {
            printf("GPIO %d: %d\n", GPIO_PIN, value);
        }
    }

    // Release the GPIO pin
    gpiod_gpio_close(&req);

    // Exit libgpiod
    gpiod_exit(&ctx);

    return 0;
}

