#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>

// Define the GPIO numbers
#define GPIO4 4
#define GPIO17 17
#define GPIO18 18

// Define the PWM frequency
#define PWM_FREQ 1000

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up PWM on GPIO 4, 17, and 18
    if (gpioSetMode(GPIO4, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO17, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO18, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Set the initial duty cycle
    if (gpioWrite(GPIO4, 0) < 0) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(GPIO17, 0) < 0) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(GPIO18, 0) < 0) {
        perror("gpioWrite");
        gpioTerminate();
        return 1;
    }

    // Set the PWM frequency
    if (gpioPwmWrite(GPIO4, PWM_FREQ) < 0) {
        perror("gpioPwmWrite");
        gpioTerminate();
        return 1;
    }
    if (gpioPwmWrite(GPIO17, PWM_FREQ) < 0) {
        perror("gpioPwmWrite");
        gpioTerminate();
        return 1;
    }
    if (gpioPwmWrite(GPIO18, PWM_FREQ) < 0) {
        perror("gpioPwmWrite");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the current state of the GPIOs
        int state4 = gpioRead(GPIO4);
        int state17 = gpioRead(GPIO17);
        int state18 = gpioRead(GPIO18);

        // Check if the reading is valid
        if (state4 < 0 || state17 < 0 || state18 < 0) {
            printf("Invalid reading\n");
            continue;
        }

        // Print the state
        printf("GPIO 4: %d, GPIO 17: %d, GPIO 18: %d\n", state4, state17, state18);

        // Sleep for 0.1 seconds
        sleep(0.1);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

