int main() {
    // Initialize libgpiod
    gpiod_init();

    // Open the GPIO device
    gpiod_device *dev = gpiod_device_open("gpio-0", 0);
    if (!dev) {
        gpiod_perror("Failed to open GPIO device");
        return 1;
    }

    // Open the GPIO pins
    gpiod_pin *pin8 = gpiod_pin_open(dev, 8, GPIOD_DIR_OUT);
    if (!pin8) {
        gpiod_device_close(dev);
        gpiod_perror("Failed to open pin 8");
        return 1;
    }

    gpiod_pin *pin9 = gpiod_pin_open(dev, 9, GPIOD_DIR_OUT);
    if (!pin9) {
        gpiod_pin_close(pin8);
        gpiod_device_close(dev);
        gpiod_perror("Failed to open pin 9");
        return 1;
    }

    gpiod_pin *pin10 = gpiod_pin_open(dev, 10, GPIOD_DIR_OUT);
    if (!pin10) {
        gpiod_pin_close(pin9);
        gpiod_pin_close(pin8);
        gpiod_device_close(dev);
        gpiod_perror("Failed to open pin 10");
        return 1;
    }

    gpiod_pin *pin11 = gpiod_pin_open(dev, 11, GPIOD_DIR_OUT);
    if (!pin11) {
        gpiod_pin_close(pin10);
        gpiod_pin_close(pin9);
        gpiod_pin_close(pin8);
        gpiod_device_close(dev);
        gpiod_perror("Failed to open pin 11");
        return 1;
    }

    gpiod_pin *pin17 = gpiod_pin_open(dev, 17, GPIOD_DIR_OUT);
    if (!pin17) {
        gpiod_pin_close(pin11);
        gpiod_pin_close(pin10);
        gpiod_pin_close(pin9);
        gpiod_pin_close(pin8);
        gpiod_device_close(dev);
        gpiod_perror("Failed to open pin 17");
        return 1;
    }

    // Set the initial state of the pins
    gpiod_pin_set_value(pin8, 1);
    gpiod_pin_set_value(pin9, 0);
    gpiod_pin_set_value(pin10, 0);
    gpiod_pin_set_value(pin11, 0);
    gpiod_pin_set_value(pin17, 1);

    // Print the initial state
    printf("Initial state: pin 8 = %d, pin 9 = %d, pin 10 = %d, pin 11 = %d, pin 17 = %d\n",
           gpiod_pin_get_value(pin8), gpiod_pin_get_value(pin9), gpiod_pin_get_value(pin10),
           gpiod_pin_get_value(pin11), gpiod_pin_get_value(pin17));

    // Run the main loop
    while (1) {
        // Set the state of the pins
        gpiod_pin_set_value(pin8, 0);
        gpiod_pin_set_value(pin9, 1);
        gpiod_pin_set_value(pin10, 1);
        gpiod_pin_set_value(pin11, 0);
        gpiod_pin_set_value(pin17, 0);

        // Print the current state
        printf("Current state: pin 8 = %d, pin 9 = %d, pin 10 = %d, pin 11 = %d, pin 17 = %d\n",
               gpiod_pin_get_value(pin8), gpiod_pin_get_value(pin9), gpiod_pin_get_value(pin10),
               gpiod_pin_get_value(pin11), gpiod_pin_get_value(pin17));

        // Sleep for 1 second
        usleep(1000000);
    }

    // Release the pins
    gpiod_pin_close(pin17);
    gpiod_pin_close(pin11);
    gpiod_pin_close(pin10);
    gpiod_pin_close(pin9);
    gpiod_pin_close(pin8);

    // Close the GPIO device
    gpiod_device_close(dev);

    // Finalize libgpiod
    gpiod_finalize();

    return 0;
}

