#include <stdio.h>
#include <stdlib.h>
#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return ret;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-2", GpioDirectionOutput);
    if (!dev) {
        fprintf(stderr, "Failed to open GPIO device\n");
        gpiod_exit();
        return 1;
    }

    // Open the GPIO device for GPIO 3
    struct gpiod_device *dev3 = gpiod_device_open("gpio-3", GpioDirectionOutput);
    if (!dev3) {
        fprintf(stderr, "Failed to open GPIO device\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Open the GPIO device for GPIO 17
    struct gpiod_device *dev17 = gpiod_device_open("gpio-17", GpioDirectionOutput);
    if (!dev17) {
        fprintf(stderr, "Failed to open GPIO device\n");
        gpiod_device_close(dev3);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the state of GPIO 2
    ret = gpiod_device_set_value(dev, 0, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 2: %d\n", ret);
        gpiod_device_close(dev17);
        gpiod_device_close(dev3);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the state of GPIO 3
    ret = gpiod_device_set_value(dev3, 0, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 3: %d\n", ret);
        gpiod_device_close(dev17);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the state of GPIO 17
    ret = gpiod_device_set_value(dev17, 0, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 17: %d\n", ret);
        gpiod_device_close(dev3);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Wait for 2 seconds
    sleep(2);

    // Set the state of GPIO 2
    ret = gpiod_device_set_value(dev, 0, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 2: %d\n", ret);
        gpiod_device_close(dev17);
        gpiod_device_close(dev3);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the state of GPIO 3
    ret = gpiod_device_set_value(dev3, 0, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 3: %d\n", ret);
        gpiod_device_close(dev17);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the state of GPIO 17
    ret = gpiod_device_set_value(dev17, 0, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 17: %d\n", ret);
        gpiod_device_close(dev3);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Close the GPIO devices
    gpiod_device_close(dev17);
    gpiod_device_close(dev3);
    gpiod_device_close(dev);

    // Exit libgpiod
    gpiod_exit();

    return 0;
}

