        clock_gettime(CLOCK_REALTIME, &ts);
        nanosleep(&ts, NULL);

        // Toggle the state of GPIO 17 and 27
        gpiod_gpio_set_value(gpio17, 1 - gpiod_gpio_get_value(gpio17));
        gpiod_gpio_set_value(gpio27, 1 - gpiod_gpio_get_value(gpio27));
    }

    // Cleanly close the GPIO devices
    gpiod_gpio_close(gpio27);
    gpiod_gpio_close(gpio17);
    gpiod_device_close(dev27);
    gpiod_device_close(dev);

    // Cleanly exit libgpiod
    gpiod_exit();
    return 0;
}

