#include <stdio.h>
#include <stdlib.h>
#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    gpiod_init();

    // Open the GPIO device
    gpiod_device *dev = gpiod_device_open("gpio-0", 0);
    if (!dev) {
        gpiod_exit();
        return 1;
    }

    // Open the GPIO pins
    gpiod_pin *pin8 = gpiod_pin_open(dev, 8, GPIOD_DIR_OUT);
    gpiod_pin *pin9 = gpiod_pin_open(dev, 9, GPIOD_DIR_OUT);
    gpiod_pin *pin10 = gpiod_pin_open(dev, 10, GPIOD_DIR_OUT);
    gpiod_pin *pin11 = gpiod_pin_open(dev, 11, GPIOD_DIR_OUT);
    gpiod_pin *pin23 = gpiod_pin_open(dev, 23, GPIOD_DIR_OUT);
    if (!pin8 || !pin9 || !pin10 || !pin11 || !pin23) {
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the initial state of the pins
    gpiod_pin_set_value(pin8, 0);
    gpiod_pin_set_value(pin9, 0);
    gpiod_pin_set_value(pin10, 0);
    gpiod_pin_set_value(pin11, 0);
    gpiod_pin_set_value(pin23, 0);

    // Main loop
    for (int i = 0; i < 3; i++) {
        // Set the pins to high
        gpiod_pin_set_value(pin8, 1);
        gpiod_pin_set_value(pin9, 1);
        gpiod_pin_set_value(pin10, 1);
        gpiod_pin_set_value(pin11, 1);
        gpiod_pin_set_value(pin23, 1);
        printf("Cycle %d: All pins high\n", i + 1);

        // Wait for 1 second
        sleep(1);

        // Set the pins to low
        gpiod_pin_set_value(pin8, 0);
        gpiod_pin_set_value(pin9, 0);
        gpiod_pin_set_value(pin10, 0);
        gpiod_pin_set_value(pin11, 0);
        gpiod_pin_set_value(pin23, 0);
        printf("Cycle %d: All pins low\n", i + 1);

        // Wait for 1 second
        sleep(1);
    }

    // Release the pins
    gpiod_pin_close(pin8);
    gpiod_pin_close(pin9);
    gpiod_pin_close(pin10);
    gpiod_pin_close(pin11);
    gpiod_pin_close(pin23);

    // Close the GPIO device
    gpiod_device_close(dev);

    // Exit libgpiod
    gpiod_exit();

    return 0;
}

