    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-27", GPIOD_DEVICE_TYPE_OUTPUT);
    if (!dev) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Get the GPIO pin
    struct gpiod_pin *pin = gpiod_device_get_pin(dev, 0);
    if (!pin) {
        fprintf(stderr, "gpiod_device_get_pin failed\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the initial state
    ret = gpiod_pin_set_value(pin, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_pin_set_value failed: %d\n", ret);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set up the event loop
    struct gpiod_event *event = gpiod_event_create();
    if (!event) {
        fprintf(stderr, "gpiod_event_create failed\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    struct gpiod_event_callback *cb = gpiod_event_create_callback(event, GPIOD_EVENT_VALUE, gpiod_event_callback_value, pin);
    if (!cb) {
        fprintf(stderr, "gpiod_event_create_callback failed\n");
        gpiod_event_destroy(event);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Start the event loop
    gpiod_event_start(event);

    // Main loop
    while (1) {
        // Sleep for 0.1 seconds
        usleep(100000);

        // Print the current state
        ret = gpiod_pin_get_value(pin);
