#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x03
#define I2C_REG_STATUS 0x00
#define I2C_REG_DATA 0x01

int main() {
    int fd;
    void* mem;
    unsigned char status;
    unsigned char data[3];

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("set I2C address");
        close(fd);
        return 1;
    }

    // Read status register
    if (read(fd, &status, 1) != 1) {
        perror("read status");
        close(fd);
        return 1;
    }

    // Check if device is present
    if (status & (1 << 7)) {
        printf("Device not found\n");
        close(fd);
        return 1;
    }

    // Map I2C memory
    mem = mmap(NULL, 256, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mem == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return 1;
    }

    // Read temperature and pressure
    if (read(fd, data, 3) != 3) {
        perror("read data");
        munmap(mem, 256);
        close(fd);
        return 1;
    }

    // Unmap I2C memory
    munmap(mem, 256);

    // Print readings
    printf("Temperature: %.2f C\n", (data[0] * 0.01);
    printf("Pressure: %.2f hPa\n", (data[1] * 0.01);
    printf("Humidity: %.2f %%\n", (data[2] * 0.01));

    // Close I2C device
    close(fd);

    return 0;
}

