        return 1;
    }

    // Check if the device is valid
    if (!gpiod_device_valid(dev)) {
        fprintf(stderr, "Invalid device 'gpio-17'\n");
        gpiod_exit();
        return 1;
    }

    // Get the GPIO pin
    struct gpiod_pin *pin = gpiod_device_get_pin(dev, 0);
    if (!pin) {
        fprintf(stderr, "Failed to get pin 0 of device 'gpio-17'\n");
        gpiod_exit();
        return 1;
    }

    // Check if the pin is valid
    if (!gpiod_pin_valid(pin)) {
        fprintf(stderr, "Invalid pin 0 of device 'gpio-17'\n");
        gpiod_exit();
        return 1;
    }

    // Set the pin to output
    ret = gpiod_pin_set_direction(pin, GPIOD_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set direction of pin 0 of device 'gpio-17': %d\n", ret);
        gpiod_exit();
        return 1;
    }

    // Set the pin high
    ret = gpiod_pin_set_value(pin, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set value of pin 0 of device 'gpio-17': %d\n", ret);
        gpiod_exit();
        return 1;
    }

