#include <sys/mman.h>
#include <sys/stat.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x76
#define I2C_BUFFER_SIZE 32

int main() {
    int fd;
    void* mem;
    int i, ret;
    unsigned char buffer[I2C_BUFFER_SIZE];
    struct i2c_client *client;
    struct i2c_dev *dev;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address
    ret = ioctl(fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    // Map I2C device memory
    mem = mmap(NULL, I2C_BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mem == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return 1;
    }

    // Get I2C device structure
    dev = (struct i2c_dev *) mem;
    if (dev->dev->addr != I2C_ADDRESS) {
        perror("i2c_dev->addr");
        munmap(mem, I2C_BUFFER_SIZE);
        close(fd);
        return 1;
    }

    // Initialize BME280
    ret = ioctl(fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("ioctl");
        munmap(mem, I2C_BUFFER_SIZE);
        close(fd);
        return 1;
    }

    // Read temperature and pressure
    for (i = 0; i < 3; i++) {
        ret = ioctl(fd, I2C_SLAVE, I2C_ADDRESS);
        if (ret < 0) {
            perror("ioctl");
            munmap(mem, I2C_BUFFER_SIZE);
            close(fd);
            return 1;
        }

        ret = read(fd, buffer, I2C_BUFFER_SIZE);
        if (ret < 0) {
            perror("read");
            munmap(mem, I2C_BUFFER_SIZE);
            close(fd);
            return 1;
        }

        // Extract temperature and pressure from buffer
        unsigned char t = (buffer[0] << 8) | buffer[1];
        unsigned char p = (buffer[2] << 8) | buffer[3];

        printf("Reading %d %d\n", t, p);

        // Wait 5 seconds
        sleep(5);
    }

    // Release I2C device
    munmap(mem, I2C_BUFFER_SIZE);
    close(fd);

    return 0;
}

