int main() {
    gpiod_context_t ctx;
    gpiod_device_t *dev;
    gpiod_gpio_t *gpio;
    gpiod_gpio_flags_t flags;
    gpiod_gpio_value_t value;

    // Initialize libgpiod
    if (gpiod_init(&ctx) != 0) {
        fprintf(stderr, "gpiod_init failed\n");
        return 1;
    }

    // Open the device
    dev = gpiod_device_open(&ctx, "gpio-17", GpioDevFlags::kNoPull, NULL);
    if (!dev) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_exit(&ctx);
        return 1;
    }

    // Get the GPIO device
    gpio = gpiod_device_get_gpio(dev);
    if (!gpio) {
        fprintf(stderr, "gpiod_device_get_gpio failed\n");
        gpiod_device_close(dev);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set the GPIO flags
    flags = gpiod_gpio_flags_get(gpio, GPIO_FLAG_INIT);
    if (gpiod_gpio_flags_set(gpio, flags | GPIO_FLAG_OUTPUT) != 0) {
        fprintf(stderr, "gpiod_gpio_flags_set failed\n");
        gpiod_device_close(dev);
        gpiod_exit(&ctx);
        return 1;
    }

    // Set the GPIO value
    value = gpiod_gpio_value_get(gpio, GPIO_VALUE_INIT);
    if (gpiod_gpio_value_set(gpio, value) != 0) {
        fprintf(stderr, "gpiod_gpio_value_set failed\n");
        gpiod_device_close(dev);
        gpiod_exit(&ctx);
        return 1;
    }

    // Main loop
    while (1) {
        // Get the current value
        value = gpiod_gpio_value_get(gpio);
        printf("Current value: %d\n", value);

        // Sleep for 1 second
        gpiod_gpio_flags_set(gpio, GPIO_FLAG_SUSPEND);
        gpiod_gpio_flags_clear(gpio, GPIO_FLAG_SUSPEND);
        usleep(1000000);

        // Toggle the value
        value = (value + 1) % 2;
        if (gpiod_gpio_value_set(gpio, value) != 0) {
            fprintf(stderr, "gpiod_gpio_value_set failed\n");
            gpiod_device_close(dev);
            gpiod_exit(&ctx);
            return 1;
        }
    }

    // Clean up
    gpiod_gpio_flags_clear(gpio, GPIO_FLAG_SUSPEND);
    gpiod_gpio_flags_clear(gpio, GPIO_FLAG_OUTPUT);
    gpiod_gpio_value_clear(gpio);
    gpiod_device_close(dev);
    gpiod_exit(&ctx);
    return 0;
}

