#define BAUD_RATE 9600
#define BUFFER_SIZE 256

int main() {
    int fd, pin, err;
    struct termios oldt, newt;
    struct termios tty;
    struct timeval tv;
    char buffer[BUFFER_SIZE];
    int bytes_read;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open serial port
    fd = open("/dev/ttyUSB0", O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Set up serial port
    tcgetattr(fd, &oldt);
    tcgetattr(fd, &newt);
    cfsetispeed(&newt, BAUD_RATE);
    cfsetospeed(&newt, BAUD_RATE);
    tcsetattr(fd, TCSANOW, &newt);

    // Set up timeout
    struct timeval tv = {0, 0};
    tv.tv_sec = 1;
    tv.tv_usec = 0;
    if (ioctl(fd, FIONREAD, &tv) < 0) {
        perror("FIONREAD");
        close(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read from serial port
        bytes_read = read(fd, buffer, BUFFER_SIZE);
        if (bytes_read < 0) {
            if (EINTR(errno)) {
                continue;
            } else {
                perror("read");
                close(fd);
                gpioTerminate();
                return 1;
            }
        }

        // Print to standard output
        printf("%s", buffer);

        // Check for device response
        if (bytes_read > 0) {
            if (ioctl(fd, FIONREAD, &tv) < 0) {
                perror("FIONREAD");
                close(fd);
                gpioTerminate();
                return 1;
            }
        }

        // Sleep for 0.1 seconds
        usleep(100000);
    }

    // Clean up
    close(fd);
    gpioTerminate();
    return 0;
}

