#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <gpiod/gpiod.h>

int main(int argc, char *argv[]) {
    // Initialize libgpiod
    gpiod_init();

    // Open the GPIO device
    gpiod_device *dev = gpiod_device_open("gpio-8", GpioDirectionOutput);
    if (!dev) {
        perror("Failed to open GPIO device");
        return 1;
    }

    // Set the initial state of the GPIO pin
    gpiod_value_t value = gpiod_value_new(GpioValueHigh);
    if (!gpiod_value_set(dev, 8, value)) {
        perror("Failed to set GPIO value");
        gpiod_device_close(dev);
        return 1;
    }

    // Set up a signal handler to clean up on interrupt
    struct sigaction sa;
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        gpiod_device_close(dev);
        return 1;
    }

    while (1) {
        // Print the current state of the GPIO pin
        gpiod_value_t state = gpiod_value_get(dev, 8);
        printf("GPIO 8: %s\n", gpiod_value_to_string(state));

        // Wait for 0.001 seconds
        usleep(1000);

        // Toggle the state of the GPIO pin
        gpiod_value_t new_state = gpiod_value_new(gpiod_value_get(dev, 8) == GpioValueLow ? GpioValueHigh : GpioValueLow);
        if (!gpiod_value_set(dev, 8, new_state)) {
            perror("Failed to set GPIO value");
            gpiod_device_close(dev);
            return 1;
        }
    }

    // Clean up on exit
    gpiod_device_close(dev);
    return 0;
}

