#define ADXL345_ADDRESS 0x53
#define ADXL345_DATA_REG 0x32

int main() {
    int fd;
    int i2c_fd;
    int status;
    unsigned char data[3];
    unsigned int x, y, z;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C bus parameters
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("ioctl");
        return 1;
    }

    // Read data from ADXL345
    if (read(i2c_fd, data, 3) != 3) {
        perror("read");
        return 1;
    }

    // Convert data to acceleration values
    x = (data[0] << 8) | data[1];
    y = (data[2] << 8) | data[3];
    z = (data[4] << 8) | data[5];

    // Print acceleration values
    printf("x: %d, y: %d, z: %d\n", x, y, z);

    // Release I2C device
    close(i2c_fd);
    close(fd);

    return 0;
}

