    gpiod_gpio *gpio23 = gpiod_gpio_open(dev, 23);
    gpiod_gpio *gpio24 = gpiod_gpio_open(dev, 24);
    gpiod_gpio *gpio25 = gpiod_gpio_open(dev, 25);
    gpiod_gpio *gpio27 = gpiod_gpio_open(dev, 27);
    if (!gpio4 || !gpio17 || !gpio18 || !gpio22 || !gpio23 || !gpio24 || !gpio25 || !gpio27) {
        gpiod_error_print("Failed to open GPIO pins");
        gpiod_device_close(dev);
        return 1;
    }

    // Set the initial state of the GPIO pins
    gpiod_gpio_set_value(gpio4, 0);
    gpiod_gpio_set_value(gpio17, 0);
    gpiod_gpio_set_value(gpio18, 0);
    gpiod_gpio_set_value(gpio22, 0);
    gpiod_gpio_set_value(gpio23, 0);
    gpiod_gpio_set_value(gpio24, 0);
    gpiod_gpio_set_value(gpio25, 0);
    gpiod_gpio_set_value(gpio27, 0);

    // Set up the callback function
    gpiod_gpio_set_callback(gpio4, GPIOD_GPIO_EDGE_RISING, gpiod_gpio_callback, gpio4);
    gpiod_gpio_set_callback(gpio17, GPIOD_GPIO_EDGE_RISING, gpiod_gpio_callback, gpio17);
    gpiod_gpio_set_callback(gpio18, GPIOD_GPIO_EDGE_RISING, gpiod_gpio_callback, gpio18);
    gpiod_gpio_set_callback(gpio22, GPIOD_GPIO_EDGE_RISING, gpiod_gpio_callback, gpio22);
    gpiod_gpio_set_callback(gpio23, GPIOD_GPIO_EDGE_RISING, gpiod_gpio_callback, gpio23);
    gpiod_gpio_set_callback(gpio24, GPIOD_GPIO_EDGE_RISING, gpiod_gpio_callback, gpio24);
    gpiod_gpio_set_callback(gpio25, GPIOD_GPIO_EDGE_RISING, gpiod_gpio_callback, gpio25);
    gpiod_gpio_set_callback(gpio27, GPIOD_GPIO_EDGE_RISING, gpiod_gpio_callback, gpio27);

    // Main loop
    while (1) {
        // Print the current state of the GPIO pins
        printf("GPIO 4: %d, GPIO 17: %d, GPIO 18: %d, GPIO 22: %d, GPIO 23: %d, GPIO 24: %d, GPIO 25: %d, GPIO 27: %d\n",
               gpiod_gpio_get_value(gpio4), gpiod_gpio_get_value(gpio17), gpiod_gpio_get_value(gpio18), gpiod_gpio_get_value(gpio22), gpiod_gpio_get_value(gpio23), gpiod_gpio_get_value(gpio24), gpiod_gpio_get_value(gpio25), gpiod_gpio_get_value(gpio27));

        // Sleep for 0.05 seconds
        usleep(50000);

        // Check if the device is absent
        if (gpiod_device_is_absent(dev)) {
            gpiod_error_print("Device is absent");
            break;
