    gpiod_gpio_release(gpio22);
    gpiod_gpio_release(gpio23);
    gpiod_gpio_release(gpio24);
    gpiod_gpio_release(gpio25);
    gpiod_gpio_release(gpio27);

    // Release the GPIO device
    gpiod_device_close(dev);

    // Clean up libgpiod
    gpiod_exit();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <gpiod/gpiod.h>

int main(int argc, char *argv[]) {
    // Initialize libgpiod
    gpiod_init();

    // Open the GPIO device
    gpiod_device *dev = gpiod_device_open("gpio-4", GpioDirectionOutput);
    if (!dev) {
        perror("Failed to open GPIO device");
        return 1;
    }

    // Open the GPIO device for GPIO 17
    gpiod_device *dev17 = gpiod_device_open("gpio-17", GpioDirectionOutput);
    if (!dev17) {
        perror("Failed to open GPIO device");
        gpiod_device_close(dev);
        return 1;
    }

    // Open the GPIO device for GPIO 27
    gpiod_device *dev27 = gpiod_device_open("gpio-27", GpioDirectionOutput);
    if (!dev27) {
        perror("Failed to open GPIO device");
        gpiod_device_close(dev17);
        gpiod_device_close(dev);
        return 1;
    }

    // Set the initial state of GPIO 4, 17, and 27 to low
    gpiod_device_set(dev, 4, 0);
    gpiod_device_set(dev17, 0);
    gpiod_device_set(dev27, 0);

    // Main loop
    while (1) {
        // Set the state of GPIO 4, 17, and 27 to high
        gpiod_device_set(dev, 4, 1);
        gpiod_device_set(dev17, 1);
        gpiod_device_set(dev27, 1);

        // Print the state to standard output
        printf("GPIO 4: %d, GPIO 17: %d, GPIO 27: %d\n", gpiod_device_get(dev, 4), gpiod_device_get(dev17, 0), gpiod_device_get(dev27, 0));

        // Sleep for 0.5 seconds
        sleep(0.5);

        // Set the state of GPIO 4, 17, and 27 to low
        gpiod_device_set(dev, 4, 0);
        gpiod_device_set(dev17, 0);
        gpiod_device_set(dev27, 0);
    }

    // Close the GPIO devices
    gpiod_device_close(dev27);
    gpiod_device_close(dev17);
    gpiod_device_close(dev);

    // Wait for the program to finish
    wait(NULL);

    // Release libgpiod
    gpiod_exit();
    return 0;
}

#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up PWM on GPIO 18
    if (gpioSetMode(18, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency to 100 Hz
    if (gpioPWM(18, PI_HIGH, 1000) < 0) {
        perror("gpioPWM");
        gpioTerminate();
        return 1;
    }

    // Set PWM duty cycle to 50%
    if (gpioPWM(18, PI_HIGH, 500) < 0) {
        perror("gpioPWM");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Print current PWM state
        printf("PWM state: %d\n", gpioGet(18));

        // Sleep for 0.1 seconds
        usleep(100000);

        // Toggle PWM state
        gpioPWM(18, PI_HIGH, 500);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-4", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Open the GPIO pin
    struct gpiod_gpio *gpio = gpiod_gpio_open(dev, 4);
    if (!gpio) {
        fprintf(stderr, "gpiod_gpio_open failed\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Open the GPIO pin for writing
    struct gpiod_gpio_request *req = gpiod_gpio_request(gpio, 0);
    if (!req) {
        fprintf(stderr, "gpiod_gpio_request failed\n");
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the initial state to LOW
    ret = gpiod_gpio_set_value(req, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_gpio_release(req);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Print the initial state
    printf("Initial state: LOW\n");

    // Set the state to HIGH for 1 second
    struct gpiod_timer *timer = gpiod_timer_create(req, 0, 1000);
    if (!timer) {
        fprintf(stderr, "gpiod_timer_create failed\n");
        gpiod_gpio_release(req);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the state to HIGH
    ret = gpiod_gpio_set_value(req, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_timer_delete(timer);
        gpiod_gpio_release(req);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
