    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return ret;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-17", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_exit();
        return 1;
    }

    // Open the GPIO device for GPIO 21
    struct gpiod_device *dev21 = gpiod_device_open("gpio-21", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev21) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Get the GPIO handle for GPIO 17
    struct gpiod_gpio *gpio17 = gpiod_device_get_gpio(dev, 17);
    if (!gpio17) {
        fprintf(stderr, "gpiod_device_get_gpio failed\n");
        gpiod_device_close(dev21);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Get the GPIO handle for GPIO 21
    struct gpiod_gpio *gpio21 = gpiod_device_get_gpio(dev21, 21);
    if (!gpio21) {
        fprintf(stderr, "gpiod_device_get_gpio failed\n");
        gpiod_device_close(dev21);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the initial state of GPIO 17 to LOW
    ret = gpiod_gpio_set_value(gpio17, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_device_close(dev21);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the initial state of GPIO 21 to HIGH
    ret = gpiod_gpio_set_value(gpio21, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_device_close(dev21);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Main loop
    while (1) {
        // Get the current state of GPIO 17
        int state17 = gpiod_gpio_get_value(gpio17);
        // Get the current state of GPIO 21
        int state21 = gpiod_gpio_get_value(gpio21);

        // Print the current state
        printf("GPIO 17: %d, GPIO 21: %d\n", state17, state21);

        // Sleep for 0.1 seconds
        usleep(100000);

        // Check if the device is absent
        if (gpiod_device_is_absent(dev) || gpiod_device_is_absent(dev21)) {
            fprintf(stderr, "Device absent\n");
            gpiod_device_close(dev21);
            gpiod_device_close(dev);
            gpiod_exit();
            return 1;
        }
