    gpiod_gpio_release(gpio17);
    gpiod_gpio_release(gpio21);

    // Close the GPIO devices
    gpiod_device_close(dev21);
    gpiod_device_close(dev);

    // Exit libgpiod
    gpiod_exit();
    return 0;
}

#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set up PWM on GPIO 4
    if (gpioSetMode(4, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Set up PWM on GPIO 22
    if (gpioSetMode(22, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    if (gpioPWM(4, PI_HIGH, 1000) < 0) {
        perror("gpioPWM");
        gpioTerminate();
        return 1;
    }

    // Set PWM duty cycle
    if (gpioPWM(4, PI_LOW, 500) < 0) {
        perror("gpioPWM");
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Print current state
        printf("GPIO 4: %d\n", gpioRead(4));

        // Sleep for 0.01 seconds
        usleep(10000);

        // Toggle PWM duty cycle
        if (gpioPWM(4, PI_HIGH, 1000) < 0) {
            perror("gpioPWM");
            gpioTerminate();
            return 1;
        }
        if (gpioPWM(4, PI_LOW, 500) < 0) {
            perror("gpioPWM");
            gpioTerminate();
            return 1;
        }
    }

    // Clean up
    gpioTerminate();
    return 0;
}

