#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return ret;
    }

    // Get the device handle for GPIO 24
    struct gpiod_device *dev = gpiod_device_get("gpio-24", NULL);
    if (!dev) {
        fprintf(stderr, "Failed to get device handle for GPIO 24\n");
        gpiod_exit();
        return 1;
    }

    // Get the device's properties
    struct gpiod_device_properties props;
    if (gpiod_device_get_properties(dev, &props) < 0) {
        fprintf(stderr, "Failed to get device properties\n");
        gpiod_device_put(dev);
        gpiod_exit();
        return 1;
    }

    // Check if the device is a GPIO device
    if (props.type != GPIOD_TYPE_GPIO) {
        fprintf(stderr, "Device is not a GPIO device\n");
        gpiod_device_put(dev);
        gpiod_exit();
        return 1;
    }

    // Get the GPIO pin's direction
    uint32_t direction = props.direction;
    if (direction != GPIOD_DIR_OUT) {
        fprintf(stderr, "Device is not an output pin\n");
        gpiod_device_put(dev);
        gpiod_exit();
        return 1;
    }

    // Set the pin to high
    ret = gpiod_device_set_value(dev, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set pin high: %d\n", ret);
        gpiod_device_put(dev);
        gpiod_exit();
        return ret;
    }

    // Print the current state
    printf("GPIO 24 is high\n");

    // Release the device
    gpiod_device_put(dev);

    // Exit
    gpiod_exit();
    return 0;
}

