#include <stdio.h>
#include <stdlib.h>
#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    gpiod_init();

    // Open the GPIO device
    gpiod_device *dev = gpiod_device_open("gpio-23", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        fprintf(stderr, "Failed to open GPIO device\n");
        return EXIT_FAILURE;
    }

    // Get the GPIO pin
    gpiod_gpio *gpio = gpiod_gpio_open(dev, 23);
    if (!gpio) {
        fprintf(stderr, "Failed to open GPIO pin\n");
        gpiod_device_close(dev);
        return EXIT_FAILURE;
    }

    // Set the GPIO pin to output
    if (gpiod_gpio_direction(gpio, GPIOD_DIR_OUT) != 0) {
        fprintf(stderr, "Failed to set GPIO pin to output\n");
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        return EXIT_FAILURE;
    }

    // Set the GPIO pin high
    if (gpiod_gpio_value(gpio, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO pin high\n");
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        return EXIT_FAILURE;
    }

    // Print the current state
    printf("GPIO 23 is high\n");

    // Wait for 5 seconds
    sleep(5);

    // Set the GPIO pin low
    if (gpiod_gpio_value(gpio, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO pin low\n");
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        return EXIT_FAILURE;
    }

    // Print the current state
    printf("GPIO 23 is low\n");

    // Close the GPIO pin and device
    gpiod_gpio_close(gpio);
    gpiod_device_close(dev);

    // Release the GPIO device
    gpiod_device_release(dev);

    // Finalize libgpiod
    gpiod_finalize();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod/gpiod.h>

int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return ret;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-17", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        fprintf(stderr, "Failed to open GPIO device\n");
        gpiod_exit();
        return 1;
    }

    // Open the GPIO device for GPIO 27
    struct gpiod_device *dev27 = gpiod_device_open("gpio-27", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev27) {
        fprintf(stderr, "Failed to open GPIO device\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Get the GPIO handle for GPIO 17
    struct gpiod_gpio *gpio17 = gpiod_device_get_gpio(dev, 17);
    if (!gpio17) {
        fprintf(stderr, "Failed to get GPIO handle for GPIO 17\n");
        gpiod_device_close(dev27);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Get the GPIO handle for GPIO 27
    struct gpiod_gpio *gpio27 = gpiod_device_get_gpio(dev27, 27);
    if (!gpio27) {
        fprintf(stderr, "Failed to get GPIO handle for GPIO 27\n");
        gpiod_device_close(dev27);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the initial state of GPIO 17 to LOW
    ret = gpiod_gpio_set_value(gpio17, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 17 to LOW\n");
        gpiod_device_close(dev27);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the initial state of GPIO 27 to HIGH
    ret = gpiod_gpio_set_value(gpio27, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 27 to HIGH\n");
        gpiod_device_close(dev27);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Main loop
    while (1) {
        // Get the current state of GPIO 17
        int state17 = gpiod_gpio_get_value(gpio17);
        // Get the current state of GPIO 27
        int state27 = gpiod_gpio_get_value(gpio27);

        // Print the current state
        printf("GPIO 17: %d, GPIO 27: %d\n", state17, state27);

        // Wait for 0.2 seconds
        usleep(200000);

        // Toggle the state of GPIO 17
        ret = gpiod_gpio_set_value(gpio17, !state17);
        if (ret < 0) {
            fprintf(stderr, "Failed to toggle GPIO 17\n");
            gpiod_device_close(dev27);
            gpiod_device_close(dev);
            gpiod_exit();
            return 1;
        }

        // Toggle the state of GPIO 27
        ret = gpiod_gpio_set_value(gpio27, !state27);
        if (ret < 0) {
            fprintf(stderr, "Failed to toggle GPIO 27\n");
            gpiod_device_close(dev27);
            gpiod_device_close(dev);
            gpiod_exit();
            return 1;
        }
    }

    // Release the GPIO devices
    gpiod_device_close(dev27);
    gpiod_device_close(dev);

    // Exit cleanly
    gpiod_exit();
    return 0;
}

