#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Set GPIO 18, 21, 22 as PWM outputs
    if (gpioSetMode(18, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(21, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(22, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency and duty cycle
    if (gpioPWM(18, PI_HIGH, 1000, 50) < 0) {
        perror("gpioPWM");
        gpioTerminate();
        return 1;
    }
    if (gpioPWM(21, PI_HIGH, 1000, 50) < 0) {
        perror("gpioPWM");
        gpioTerminate();
        return 1;
    }
    if (gpioPWM(22, PI_HIGH, 1000, 50) < 0) {
        perror("gpioPWM");
        gpioTerminate();
        return 1;
    }

    // Print initial state
    printf("GPIO 18: %d\n", gpioRead(18));
    printf("GPIO 21: %d\n", gpioRead(21));
    printf("GPIO 22: %d\n", gpioRead(22));

    // Sleep for 5 seconds
    sleep(5);

    // Set PWM to 0
    if (gpioPWM(18, PI_LOW, 0, 0) < 0) {
        perror("gpioPWM");
        gpioTerminate();
        return 1;
    }
    if (gpioPWM(21, PI_LOW, 0, 0) < 0) {
        perror("gpioPWM");
        gpioTerminate();
        return 1;
    }
    if (gpioPWM(22, PI_LOW, 0, 0) < 0) {
        perror("gpioPWM");
        gpioTerminate();
        return 1;
    }

    // Print final state
    printf("GPIO 18: %d\n", gpioRead(18));
    printf("GPIO 21: %d\n", gpioRead(21));
    printf("GPIO 22: %d\n", gpioRead(22));

    // Release GPIO
    gpioTerminate();

    return 0;
}

