#include <stdlib.h>

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up PWM on GPIO 16
    if (gpioSetMode(16, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 16 as output\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    if (gpioPWM(16, PI_HIGH, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM on GPIO 16\n");
        gpioTerminate();
        return 1;
    }

    // Run indefinitely
    while (1) {
        // Set PWM to 50%
        gpioPWM(16, PI_HIGH, 500);
        printf("PWM state: HIGH\n");
        // Sleep for 1 second
        sleep(1);
        // Set PWM to 0%
        gpioPWM(16, PI_LOW, 0);
        printf("PWM state: LOW\n");
        // Sleep for 1 second
        sleep(1);
    }

    // Release resources
    gpioTerminate();
    return 0;
}

