#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x29
#define I2C_ADDRESS_TCS34725 0x44

int main(int argc, char *argv[]) {
    int fd;
    struct i2c_client *client;
    struct i2c_dev *dev;
    struct i2c_msg msg;
    struct i2c_file *file;
    struct i2c_file *file_read;
    struct i2c_file *file_write;
    struct i2c_file *file_read_lock;
    struct i2c_file *file_write_lock;
    int ret;
    int i;
    int count = 0;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    // Check if device is present
    ret = ioctl(fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("ioctl");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Create I2C client
    client = i2c_new_client(fd, I2C_ADDRESS_TCS34725, NULL);
    if (!client) {
        perror("i2c_new_client");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Create I2C file
    dev = i2c_dev_new(client, I2C_ADDRESS_TCS34725);
    if (!dev) {
        perror("i2c_dev_new");
        i2c_free_client(client);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Create I2C file for reading
    file = i2c_file_new(dev, I2C_ADDRESS_TCS34725, I2C_READ, NULL);
