    // Initialize libgpiod
    gpiod_init();

    // Open the GPIO device
    gpiod_device *dev = gpiod_device_open("gpio-22", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        gpiod_exit();
        return 1;
    }

    // Open the GPIO device for GPIO 24
    gpiod_device *dev24 = gpiod_device_open("gpio-24", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev24) {
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Get the GPIO 22 and 24 devices
    gpiod_gpio *gpio22 = gpiod_gpio_open(dev, 22);
    if (!gpio22) {
        gpiod_device_close(dev24);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    gpiod_gpio *gpio24 = gpiod_gpio_open(dev24, 24);
    if (!gpio24) {
        gpiod_gpio_close(gpio22);
        gpiod_device_close(dev24);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the initial state of GPIO 22 and 24 to low
    gpiod_gpio_set_value(gpio22, 0);
    gpiod_gpio_set_value(gpio24, 0);

    // Main loop
    while (1) {
        // Set the state of GPIO 22 to high
        gpiod_gpio_set_value(gpio22, 1);
        gpiod_gpio_set_value(gpio24, 1);

        // Print the state to standard output
        printf("GPIO 22: high, GPIO 24: high\n");

        // Sleep for 0.01 seconds
        usleep(10000);

        // Set the state of GPIO 22 to low
        gpiod_gpio_set_value(gpio22, 0);
        gpiod_gpio_set_value(gpio24, 0);

        // Print the state to standard output
        printf("GPIO 22: low, GPIO 24: low\n");

        // Sleep for 0.01 seconds
        usleep(10000);
    }

    // Release the GPIO devices
    gpiod_gpio_close(gpio24);
    gpiod_gpio_close(gpio22);
    gpiod_device_close(dev24);
    gpiod_device_close(dev);

    // Exit libgpiod
    gpiod_exit();
    return 0;
}

