int main(int argc, char *argv[]) {
    gpiod_t *gpiod;
    gpiod_device_t *device;
    gpiod_request_t *request;
    gpiod_event_t *event;
    int state = 0;

    // Initialize libgpiod
    if (gpiod_init() != 0) {
        fprintf(stderr, "Error initializing libgpiod: %s\n", gpiod_strerror());
        return 1;
    }

    // Open the device
    if (gpiod_open(&gpiod, "gpio-18", GPIOD_READ | GPIOD_WRITE) != 0) {
        fprintf(stderr, "Error opening device gpio-18: %s\n", gpiod_strerror());
        gpiod_exit();
        return 1;
    }

    // Get the device handle
    if (gpiod_get_device(&gpiod, &device) != 0) {
        fprintf(stderr, "Error getting device handle: %s\n", gpiod_strerror());
        gpiod_close(&gpiod);
        gpiod_exit();
        return 1;
    }

    // Get the request handle
    if (gpiod_get_request(&device, &request) != 0) {
        fprintf(stderr, "Error getting request handle: %s\n", gpiod_strerror());
        gpiod_close(&gpiod);
        gpiod_exit();
        return 1;
    }

    // Get the event handle
    if (gpiod_get_event(&request, &event) != 0) {
        fprintf(stderr, "Error getting event handle: %s\n", gpiod_strerror());
        gpiod_close(&gpiod);
        gpiod_exit();
        return 1;
    }

    // Set the initial state
    if (gpiod_set_value(&event, 18, state) != 0) {
        fprintf(stderr, "Error setting initial state: %s\n", gpiod_strerror());
        gpiod_close(&gpiod);
        gpiod_exit();
        return 1;
    }

    // Main loop
    while (1) {
        // Get the current state
        int current_state = gpiod_get_value(&event, 18);

        // Print the current state
        printf("%d\n", current_state);

        // Wait for 5 seconds
        gpiod_usleep(5000000);

        // Toggle the state
        state = 1 - state;

        // Set the new state
        if (gpiod_set_value(&event, 18, state) != 0) {
            fprintf(stderr, "Error setting new state: %s\n", gpiod_strerror());
            gpiod_close(&gpiod);
            gpiod_exit();
            return 1;
        }
    }

    // Release the device
    if (gpiod_close(&gpiod) != 0) {
        fprintf(stderr, "Error releasing device: %s\n", gpiod_strerror());
        return 1;
    }

    // Release the request
    if (gpiod_release_request(&request) != 0) {
        fprintf(stderr, "Error releasing request: %s\n", gpiod_strerror());
        return 1;
    }

    // Release the event
    if (gpiod_release_event(&event) != 0) {
        fprintf(stderr, "Error releasing event: %s\n", gpiod_strerror());
        return 1;
    }

    // Release the device
    if (gpiod_exit() != 0) {
        fprintf(stderr, "Error exiting libgpiod: %s\n", gpiod_strerror());
        return 1;
    }

    return 0;
}

