    if (!dev) {
        gpiod_exit();
        return 1;
    }

    // Open the GPIO pin 17
    gpiod_pin *pin17 = gpiod_pin_open(dev, 17, GPIOD_PIN_TYPE_OUTPUT);
    if (!pin17) {
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Open the GPIO pin 24
    gpiod_pin *pin24 = gpiod_pin_open(dev, 24, GPIOD_PIN_TYPE_OUTPUT);
    if (!pin24) {
        gpiod_pin_close(pin17);
        gpiod_device_close(dev);
        gpiod_exit();
        return 1;
    }

    // Set the initial state of pin 17 to LOW
    gpiod_pin_set_value(pin17, 0);

    // Set the initial state of pin 24 to HIGH
    gpiod_pin_set_value(pin24, 1);

    // Main loop
    while (1) {
        // Print the current state of the pins
        printf("Pin 17: %d, Pin 24: %d\n", gpiod_pin_get_value(pin17), gpiod_pin_get_value(pin24));

        // Wait for 0.01 seconds
        usleep(10000);

        // Toggle the state of pin 17
        gpiod_pin_set_value(pin17, 1 - gpiod_pin_get_value(pin17));

        // Toggle the state of pin 24
        gpiod_pin_set_value(pin24, 1 - gpiod_pin_get_value(pin24));
    }

    // Clean up
    gpiod_pin_close(pin24);
    gpiod_pin_close(pin17);
    gpiod_device_close(dev);
    gpiod_exit();

    return 0;
}

