    struct gpiod_gpio *gpio = gpiod_gpio_open(dev, 17, GPIOD_GPIO_DIR_IN);
    if (!gpio) {
        fprintf(stderr, "gpiod_gpio_open failed\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Open the GPIO pin for output
    struct gpiod_gpio *gpio_out = gpiod_gpio_open(dev, 24, GPIOD_GPIO_DIR_OUT);
    if (!gpio_out) {
        fprintf(stderr, "gpiod_gpio_open failed\n");
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the initial state of the output pin
    ret = gpiod_gpio_set_value(gpio_out, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_gpio_close(gpio_out);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Print the initial state of the output pin
    printf("Initial state of GPIO 24: %d\n", gpiod_gpio_get_value(gpio_out));

    // Wait for 5 seconds
    sleep(5);

