        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_gpio_close(gpio_out);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Print the final state of the output pin
    printf("Final state of GPIO 24: %d\n", gpiod_gpio_get_value(gpio_out));

    // Close the GPIO pin
    gpiod_gpio_close(gpio_out);

    // Close the GPIO pin
    gpiod_gpio_close(gpio);

    // Close the GPIO device
    gpiod_device_close(dev);

    // Exit libgpiod
    gpiod_exit();

    return EXIT_SUCCESS;
