int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    // Open the GPIO device
    struct gpiod_device *dev = gpiod_device_open("gpio-2", GPIOD_DEVICE_TYPE_GPIO);
    if (!dev) {
        fprintf(stderr, "gpiod_device_open failed\n");
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Open the GPIO pin
    struct gpiod_gpio *gpio = gpiod_gpio_open(dev, 2);
    if (!gpio) {
        fprintf(stderr, "gpiod_gpio_open failed\n");
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the initial state of the pin to LOW
    ret = gpiod_gpio_set_value(gpio, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the pin to output
    ret = gpiod_gpio_set_direction(gpio, GPIOD_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_direction failed: %d\n", ret);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the pin to HIGH
    ret = gpiod_gpio_set_value(gpio, 1);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Wait for 2 seconds
    sleep(2);

    // Set the pin to LOW
    ret = gpiod_gpio_set_value(gpio, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_set_value failed: %d\n", ret);
        gpiod_gpio_close(gpio);
        gpiod_device_close(dev);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Close the GPIO pin and device
    gpiod_gpio_close(gpio);
    gpiod_device_close(dev);

    // Exit
    gpiod_exit();
    return EXIT_SUCCESS;
}

