    if (!dev) {
        gpiod_error_print("Failed to open GPIO device");
        return 1;
    }

    // Open the GPIO pin
    gpiod_pin *pin = gpiod_pin_open(dev, 18, GPIOD_PIN_TYPE_OUTPUT);
    if (!pin) {
        gpiod_device_close(dev);
        gpiod_error_print("Failed to open GPIO pin");
        return 1;
    }

    // Open the GPIO pin for writing
    if (gpiod_pin_open(pin, GPIOD_PIN_WRITE) != 0) {
        gpiod_pin_close(pin);
        gpiod_device_close(dev);
        gpiod_error_print("Failed to open pin for writing");
        return 1;
    }

    // Set the initial state of the pin
    if (gpiod_pin_write(pin, 1) != 0) {
        gpiod_pin_close(pin);
        gpiod_device_close(dev);
        gpiod_error_print("Failed to set pin high");
        return 1;
    }

    // Main loop
    while (1) {
