#include <stdio.h>
#include <stdlib.h>
#include <termios.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define BAUD_RATE 9600
#define BUFFER_SIZE 1024

int main() {
    int fd, gpio, pin;
    struct termios oldt, newt;
    char buffer[BUFFER_SIZE];
    int bytes_read;

    // Initialize GPIO
    if (gpio = pigpio_init()) {
        printf("Failed to initialize GPIO: %d\n", gpio);
        return 1;
    }

    // Open serial port
    fd = open("/dev/ttyUSB0", O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        printf("Failed to open serial port: %d\n", errno);
        pigpio_close(gpio);
        return 1;
    }

    // Set serial port parameters
    tcgetattr(fd, &oldt);
    cfsetispeed(fd, BAUD_RATE);
    cfsetospeed(fd, BAUD_RATE);
    tcflush(fd, TCIFLUSH);
    tcgetattr(fd, &newt);
    newt.c_cflag &= ~CSIZE;
    newt.c_cflag |= CS8;
    newt.c_lflag &= ~ICANON;
    newt.c_lflag &= ~ECHO;
    newt.c_lflag &= ~ECHOE;
    newt.c_lflag &= ~ECHOK;
    newt.c_lflag &= ~ISIG;
    newt.c_cc[VMIN] = 1;
    newt.c_cc[VTIME] = 0;
    tcsetattr(fd, TCSANOW, &newt);

    // Set up interrupt handler
    pigpio_set_active_high(gpio, 17); // Set pin 17 as active high
    pigpio_set_mode(gpio, PI_INPUT);
    pigpio_pull_up(gpio, PI_PUD_DOWN);

    while (1) {
        // Read from serial port
        bytes_read = read(fd, buffer, BUFFER_SIZE);
        if (bytes_read < 0) {
            printf("Error reading from serial port: %d\n", errno);
            break;
        }

        // Print to standard output
        printf("%s", buffer);

        // Wait for 0.1 seconds
        usleep(100000);
    }

    // Clean up
    tcsetattr(fd, TCSANOW, &oldt);
    close(fd);
    pigpio_close(gpio);

    return 0;
}

