    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_request: %s\n", gpiod_strerror(ret));
        gpiod_gpio_request_release(req18);
        gpiod_gpio_request_release(req23);
        gpiod_gpio_delete(pin24);
        gpiod_gpio_delete(pin18);
        gpiod_context_free(ctx);
        return 1;
    }

    ret = gpiod_gpio_request(pin24, &req24);
    if (ret < 0) {
        fprintf(stderr, "gpiod_gpio_request: %s\n", gpiod_strerror(ret));
        gpiod_gpio_request_release(req18);
        gpiod_gpio_request_release(req23);
        gpiod_gpio_request_release(req24);
        gpiod_gpio_delete(pin23);
        gpiod_gpio_delete(pin18);
        gpiod_context_free(ctx);
        return 1;
    }

    // Set initial values
    gpiod_gpio_flags_set(req18, GPIO_FLAG_INIT);
    gpiod_gpio_flags_set(req23, GPIO_FLAG_INIT);
    gpiod_gpio_flags_set(req24, GPIO_FLAG_INIT);

    // Main loop
    while (1) {
        gpiod_gpio_flags_get(pin18, &flags18);
        gpiod_gpio_flags_get(pin23, &flags23);
        gpiod_gpio_flags_get(pin24, &flags24);

        printf("Pin 18: %d, Pin 23: %d, Pin 24: %d\n", flags18, flags23, flags24);

        // Toggle values
        gpiod_gpio_flags_clear(req18, GPIO_FLAG_INIT);
        gpiod_gpio_flags_clear(req23, GPIO_FLAG_INIT);
        gpiod_gpio_flags_clear(req24, GPIO_FLAG_INIT);

        gpiod_gpio_flags_set(req18, GPIO_FLAG_HIGH);
        gpiod_gpio_flags_set(req23, GPIO_FLAG_HIGH);
        gpiod_gpio_flags_set(req24, GPIO_FLAG_HIGH);

        gpiod_gpio_flags_clear(req18, GPIO_FLAG_HIGH);
        gpiod_gpio_flags_clear(req23, GPIO_FLAG_HIGH);
        gpiod_gpio_flags_clear(req24, GPIO_FLAG_HIGH);

        gpiod_gpio_flags_set(req18, GPIO_FLAG_LOW);
        gpiod_gpio_flags_set(req23, GPIO_FLAG_LOW);
        gpiod_gpio_flags_set(req24, GPIO_FLAG_LOW);

        gpiod_gpio_flags_clear(req18, GPIO_FLAG_LOW);
        gpiod_gpio_flags_clear(req23, GPIO_FLAG_LOW);
        gpiod_gpio_flags_clear(req24, GPIO_FLAG_LOW);

        // Sleep for 0.1 seconds
        usleep(100000);

        // Check if the device is absent
        if (gpiod_gpio_is_absent(pin18) || gpiod_gpio_is_absent(pin23) || gpiod_gpio_is_absent(pin24)) {
            fprintf(stderr, "Device absent\n");
            gpiod_gpio_request_release(req18);
            gpiod_gpio_request_release(req23);
            gpiod_gpio_request_release(req24);
            gpiod_gpio_delete(pin23);
            gpiod_gpio_delete(pin18);
            gpiod_gpio_delete(pin24);
            gpiod_context_free(ctx);
            return 1;
        }
    }

    // Release GPIO devices
    gpiod_gpio_request_release(req18);
    gpiod_gpio_request_release(req23);
    gpiod_gpio_request_release(req24);
    gpiod_gpio_delete(pin23);
    gpiod_gpio_delete(pin18);
    gpiod_gpio_delete(pin24);
    gpiod_context_free(ctx);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x68
#define I2C_ADDRESS_MPU6050 0x68

int main() {
    int fd;
    void* mem;
    unsigned char buf[14];
    int i;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("set I2C address");
        close(fd);
        return 1;
    }

    // Map I2C memory
    mem = mmap(NULL, 14, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mem == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return 1;
    }

    while (1) {
        // Read from MPU6050
        if (read(fd, buf, 14) != 14) {
            perror("read");
            break;
        }

        // Print data
        printf("Accelerometer: %f, Gyroscope: %f, Temperature: %f\n",
               (buf[0] * 16384.0 / 1024.0) / 9.81,
               (buf[1] * 16384.0 / 1024.0) / 1560.0,
               (buf[2] * 16384.0 / 1000.0));

        // Delay
        usleep(1000000);
    }

    // Unmap and close I2C device
    munmap(mem, 14);
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <gpiod/gpiod.h>

int main(int argc, char *argv[]) {
    // Initialize libgpiod
    gpiod_init();

    // Open the GPIO device
    gpiod_device *dev = gpiod_device_open("gpio-17", GpioDirectionOutput);
    if (!dev) {
        perror("Failed to open GPIO device");
        return 1;
    }

    // Set the initial state of the GPIO pin
    gpiod_value_t value = gpiod_value_new(GpioValueHigh);
    if (!gpiod_value_set(dev, 17, value)) {
        perror("Failed to set GPIO value");
        gpiod_device_close(dev);
        return 1;
    }

    // Set up a signal handler to clean up on interrupt
    struct sigaction sa;
    sa.sa_handler = sigpipe;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        gpiod_device_close(dev);
        return 1;
    }

    while (1) {
        // Print the current state of the GPIO pin
        gpiod_value_t state = gpiod_value_new(GpioValueLow);
        if (!gpiod_value_set(dev, 17, state)) {
            perror("Failed to get GPIO value");
            gpiod_device_close(dev);
            return 1;
        }
        printf("GPIO 17: %s\n", gpiod_value_to_string(state));
        sleep(0.6);
    }

    // Clean up on exit
    gpiod_device_close(dev);
    return 0;
}
